(function(){
'use strict';
const R=window.PaperRPG,RULES=R.COMBAT_RULES,$=id=>document.getElementById(id),canvas=$('world'),renderer=window.createPaperRenderer(canvas),STORE='paper-rpg-starwatch-v2',SETTINGS='paper-rpg-settings-v2';
let comparisonGear=null,fallen=false,s=R.create(),mode='title',overlayPage='',keys=new Set(),rt=runtime(),db={auto:null,slots:[null,null,null]},settings={...window.PaperAudio.DEFAULTS,effects:true,quickItems:['potion','tonic','ether']},storageOK=true,dialog=null,last=performance.now(),clock=0,autoTimer=0,hudTimer=0,toastTimer=0,announceTimer=0,saveTimer=0,pendingAction=null,returnPage='title';
function runtime(){return {mobs:[],projectiles:[],fx:[],path:[],target:null,invuln:0,attack:0,attackCd:0,dash:0,dashCd:0,moving:false,charge:0,hitstop:0,shake:0,guardAge:1,guardPerfectUsed:false,transition:false,travelCooldown:.8,travelView:null,map:null,magic:[],skillCd:{fire:0,heal:0,thunder:0},guard:false,paperFx:[],paperHurt:0,paperEffects:true,paperPaused:false};}
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readDatabase(){try{const raw=JSON.parse(localStorage.getItem(STORE));if(raw&&Array.isArray(raw.slots)){db.slots=raw.slots.slice(0,3);while(db.slots.length<3)db.slots.push(null);db.auto=raw.auto||null;}for(const [i,rec]of [...db.slots.map((r,i)=>[i,r]),['auto',db.auto]])if(rec){try{rec.state=R.validate(rec.state);if(typeof rec.savedAt!=='number')throw Error();}catch{if(i==='auto')db.auto=null;else db.slots[i]=null;}}const saved=JSON.parse(localStorage.getItem(SETTINGS));if(saved){Object.assign(settings,window.PaperAudio.settings(saved));settings.effects=saved.effects!==false;settings.quickItems=Array.from({length:3},(_,i)=>QUICK_ITEMS.includes(saved.quickItems?.[i])?saved.quickItems[i]:['potion','tonic','ether'][i]);}}catch{storageOK=false;}}
const QUICK_ITEMS=['campkit','potion','highpotion','tonic','ether','herbkit','revive'];
readDatabase();
const soundtrack=window.PaperAudio.createAudioDirector(window,settings);
const wakeSound=()=>soundtrack.unlock();document.addEventListener('pointerdown',wakeSound,true);document.addEventListener('keydown',wakeSound,true);
function persist(){try{localStorage.setItem(STORE,JSON.stringify(db));storageOK=true;return true;}catch{storageOK=false;return false;}}
function saveSettings(){soundtrack.configure(settings);try{localStorage.setItem(SETTINGS,JSON.stringify(settings));}catch{}}
function latest(){return [...db.slots,db.auto].filter(Boolean).sort((a,b)=>b.savedAt-a.savedAt)[0];}
function record(){R.syncWildlife(s,rt.mobs,rt.map||s.map);return {savedAt:Date.now(),state:JSON.parse(JSON.stringify(s))};}
function save(slot='auto'){if(mode!=='game'||fallen)return false;const rec=record();if(slot==='auto')db.auto=rec;else db.slots[slot]=rec;const ok=persist();if(slot==='auto'){saveTimer=3;$('autosave-label').textContent=ok?'✦ 旅程已自動儲存':'無法寫入瀏覽器，請匯出存檔';$('autosave-label').classList.add('show');}return ok;}
function notify(t){$('toast').textContent=t;$('toast').classList.add('show');toastTimer=Math.max(3.6,Math.min(8,String(t).length/18));}
function tone(freq=440,length=.08,type='sine',gain=.1){soundtrack.effect(freq,length,type,gain);}
function paperEffect(kind,x,y,extra={}){if(!settings.effects)return;const duration=kind==='burst'?.7:kind==='flower'?.85:.55;rt.paperFx.push({kind,x,y,duration,life:duration,...extra});if(rt.paperFx.length>64)rt.paperFx.splice(0,rt.paperFx.length-64);}
function clearInput(){keys.clear();rt.path=[];rt.target=null;rt.moving=false;rt.charge=0;$('interact-prompt').hidden=true;}
function paused(){return fallen||mode!=='game'||!$('overlay').hidden||!$('dialogue').hidden||rt.transition;}
function updateTitle(){$('continue-button').disabled=!latest();$('continue-button').title=latest()?'繼續最近一次儲存的旅程':'還沒有存檔，請選擇新的冒險';}
function modal(title,html,page=''){clearInput();dialog=null;$('dialogue').hidden=true;overlayPage=page;$('overlay').classList.toggle('paged-overlay',['inventory','shop','forge','journal','party','journey','settings','slots-save','slots-load','craft-sources','map','pause','ending'].includes(page));$('modal-content').innerHTML='<h2 id="overlay-title">'+title+'</h2>'+html;$('overlay').hidden=false;$('modal-close').hidden=page==='intro'||page==='ending';const focusId=nextModalFocus;nextModalFocus='';requestAnimationFrame(()=>{const preferred=focusId?document.getElementById(focusId):null;(preferred&&!preferred.disabled?preferred:$('modal-content').querySelector('[role="tab"][aria-selected="true"]')||$('modal-content').querySelector('input,button:not([disabled]),select')||$('modal-close')).focus({preventScroll:true});});}
function closeModal(){if(fallen){deathMenu();return;}$('overlay').hidden=true;overlayPage='';clearInput();if(mode==='game')canvas.focus({preventScroll:true});}
function dialogue(speaker,lines,after,source=null){clearInput();closeModal();const portrait=R.dialoguePortrait(s,speaker,source);$('dialogue-face').setAttribute('src',portrait.src);$('dialogue').setAttribute('data-portrait',portrait.kind);dialog={speaker,lines:Array.isArray(lines)?lines:[lines],index:0,after};$('speaker').textContent=speaker||'旅人的心聲';$('dialogue-text').textContent=dialog.lines[0];$('dialogue').hidden=false;$('dialogue-next').textContent=dialog.lines.length===1?'繼續〔空白〕':'繼續〔空白〕';$('dialogue-next').focus({preventScroll:true});}
function advanceDialogue(){if(!dialog)return;dialog.index++;if(dialog.index<dialog.lines.length){$('dialogue-text').textContent=dialog.lines[dialog.index];tone(420,.04);}else{const done=dialog.after;dialog=null;$('dialogue').hidden=true;clearInput();canvas.focus({preventScroll:true});done?.();}}
$('dialogue-next').onclick=advanceDialogue;
function timeText(sec){const m=Math.floor(sec/60);return m<60?m+' 分鐘':Math.floor(m/60)+' 小時 '+m%60+' 分鐘';}
function formatDate(n){return new Date(n).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});}
function announce(){announceTimer=3.5;$('region-announcement').textContent=R.MAPS[s.map].name;$('region-announcement').classList.add('show');}
function start(state){soundtrack.cue('clear');s=R.validate(state);fallen=false;comparisonGear=null;uiTabs={inventory:'character',ability:'overview',equipment:'weapon',shop:'supplies',shopgear:'weapon',forge:'craft',journal:'current',settings:'sound'};uiPages={};uiPageInfo={};rt=runtime();rt.map=s.map;rt.mobs=R.enemies(s);R.ensurePopulation(s,rt.mobs);R.placeParty(s);mode='game';closeModal();$('title-screen').hidden=true;$('hud').hidden=false;autoTimer=0;updateHud();announce();canvas.focus({preventScroll:true});tone(523,.2,'sine',.16);}
function newMenu(){modal('新的冒險','<p class="eyebrow">每一盞燈，都在等一個故事</p><label class="form-field">旅人的名字<input id="new-name" value="旅人" maxlength="12" autocomplete="off" aria-label="旅人的名字"></label><label class="form-field">旅途的步調<select id="new-difficulty"><option value="normal">冒險模式 · 標準戰鬥</option><option value="story">悠遊模式 · 受到傷害較低</option></select><small>兩種模式都有完整的故事、探索與結局。</small></label><p>新的冒險會更新自動存檔；三個手動存檔欄位會保留。</p><div class="modal-actions"><button data-action="close">返回</button><button class="primary" data-action="begin">踏上旅程 →</button></div>','new');}
const INTRO=[['✦','很久以前，山丘上的星燈每晚都會亮起。\n迷路的旅人，只要望向那道光，就能找到回家的方向。'],['☾','三天前，星燈忽然熄滅。\n星光散成三片，落入森林、月溪與沉睡的舊塔。'],['◇','而你，剛好在這時來到青苔村。\n風把一封沒有署名的信，輕輕放進你的行囊。\n「請替我們，把光帶回來。」']];
let introIndex=0,pendingNew=null;
function introPage(){const [icon,text]=INTRO[introIndex];modal('星燈熄滅的那一夜','<div class="story-illustration" aria-hidden="true">'+icon+'</div><p class="story-page">'+text+'</p><span class="story-dots">'+INTRO.map((_,i)=>i===introIndex?'●':'○').join(' ')+'</span><div class="modal-actions"><button data-action="skip-intro">略過故事</button><button class="primary" data-action="intro-next">'+(introIndex===2?'走進青苔村':'繼續')+' →</button></div>','intro');}
function enterNew(){pendingNew.map='village';pendingNew.x=R.center(11);pendingNew.y=R.center(10);if(!pendingNew.visited.includes('village'))pendingNew.visited.push('village');settings.quickItems=['potion','tonic','ether'];saveSettings();start(pendingNew);pendingNew=null;save();notify('你來到青苔村，行囊還空著。先找中央的苔爺聊聊。');}
function pauseMenu(){if(fallen){deathMenu();return;}if(mode!=='game')return;modal('旅人的片刻休息',interfaceShell('<p class="interface-summary">'+esc(s.name)+' · Lv.'+s.level+' · '+R.MAPS[s.map].name+' · '+timeText(s.playtime)+'</p><p class="interface-note">復活星燈：'+esc(R.currentCheckpoint(s).name)+'</p><div class="menu-grid pause-grid"><button data-action="inventory">背包</button><button data-action="journal">任務手札</button><button data-action="party">同行夥伴</button><button data-action="map">世界地圖</button><button data-action="journey">旅程回顧</button><button data-action="save">儲存旅程</button><button data-action="load-game">讀取存檔</button><button data-action="settings">設定與操作</button><button data-action="title-confirm">返回開始畫面</button></div>','<button class="primary" data-action="close">繼續冒險</button>'),'pause');}
function deathMenu(){const point=R.currentCheckpoint(s),loss=Math.ceil(s.gold*.1);modal('星光尚未熄滅','<div class="story-illustration" aria-hidden="true">✦</div><p class="story-page">你在旅途中倒下了。歇一會，再循著星光出發。</p><p>復活地點：<b>'+esc(point.name)+'</b></p><p>復活扣除 '+loss+' G（持有金幣的 10%）。生命、魔力、體力與夥伴恢復；等級、任務、物品與裝備損耗保留。</p><div class="modal-actions"><button class="primary" data-action="death-revive">在星燈復活</button><button data-action="death-load" '+(!latest()?'disabled':'')+'>讀取存檔</button></div>','death');$('modal-close').hidden=true;}
function fall(){if(fallen)return;R.syncWildlife(s,rt.mobs,rt.map||s.map);fallen=true;clearInput();deathMenu();}
function revive(){if(!fallen)return;const from={map:s.map,x:s.x,y:s.y};R.death(s);fallen=false;closeModal();transition({from,entering:true});notify('回到'+R.currentCheckpoint(s).name+'。金幣已扣除一成，裝備損耗保留。');}
function checkpointMenu(text){const point=R.currentCheckpoint(s),saved=save();modal(point.name,'<div class="story-illustration" aria-hidden="true">✦</div><p>'+esc(text)+'</p><p>'+(saved?'旅程已自動儲存。也可另存手動欄位。':'瀏覽器無法儲存，請從存檔選單匯出旅程。')+'點亮星燈不會修復裝備。</p><div class="modal-actions"><button data-action="save">另存旅程</button><button class="primary" data-action="close">繼續冒險</button></div>','checkpoint');}

const UI_TABS={inventory:[['character','角色能力'],['equipment','裝備'],['items','道具'],['exploration','探索']],ability:[['overview','總覽'],['attack','攻擊'],['defense','防禦'],['mobility','機動'],['recovery','恢復'],['techniques','絕技'],['magic','法術']],equipment:[['weapon','武器'],['body','身體防具'],['charm','護符']],shop:[['supplies','補給'],['gear','裝備'],['upgrades','強化']],shopgear:[['weapon','武器'],['body','身體防具'],['charm','護符']],forge:[['craft','特殊加工'],['repair','修理／重鑄']],journal:[['current','目前旅程'],['tasks','委託手札'],['ending','結局線索'],['log','沿途記錄']],settings:[['sound','聲音'],['effects','效果'],['controls','操作'],['display','顯示與說明']]};
let uiTabs={inventory:'character',ability:'overview',equipment:'weapon',shop:'supplies',shopgear:'weapon',forge:'craft',journal:'current',settings:'sound'},uiPages={},uiPageInfo={},nextModalFocus='',sourceRecipe=null;
const UI_OWNERS={inventory:'inventory',ability:'inventory',equipment:'inventory',shop:'shop',shopgear:'shop',forge:'forge',journal:'journal',settings:'settings'};
function uiCompact(){return (window.innerWidth||1280)<=640||(window.innerHeight||800)<=560;}
function uiCount(normal=2,compact=1){return uiCompact()?compact:normal;}
function tabControls(kind){return '<div class="interface-tabs '+(kind==='inventory'||kind==='shop'||kind==='forge'||kind==='journal'||kind==='settings'?'main-tabs':'sub-tabs')+' tabs-'+UI_TABS[kind].length+'" style="--tab-count:'+UI_TABS[kind].length+'" role="tablist" aria-label="'+({inventory:'行囊分類',ability:'角色能力分類',equipment:'裝備欄位',shop:'商店分類',shopgear:'商品欄位',forge:'工坊分類',journal:'手札分類',settings:'設定分類'}[kind])+'">'+UI_TABS[kind].map(([id,label])=>'<button id="ui-tab-'+kind+'-'+id+'" role="tab" data-ui-tab="'+kind+':'+id+'" aria-controls="ui-panel-'+kind+'" aria-selected="'+(uiTabs[kind]===id)+'" tabindex="'+(uiTabs[kind]===id?'0':'-1')+'">'+label+'</button>').join('')+'</div>';}
function tabPanel(kind,html){return '<section id="ui-panel-'+kind+'" role="tabpanel" aria-labelledby="ui-tab-'+kind+'-'+uiTabs[kind]+'">'+html+'</section>';}
function interfaceShell(content,footer='<button class="primary" data-action="close">完成</button>',tabs=''){return '<div class="interface-shell">'+tabs+'<div class="interface-scroll">'+content+'</div><div class="interface-footer">'+footer+'</div></div>';}
function pageBlocks(key,blocks,count=uiCount()){const total=Math.max(1,Math.ceil(blocks.length/count)),page=Math.max(0,Math.min(total-1,uiPages[key]||0));uiPages[key]=page;uiPageInfo[key]={owner:key.split(':')[0],total};const nav=total>1?'<nav class="interface-pager" aria-label="翻頁"><button id="page-prev-'+key+'" data-page-key="'+key+'" data-page-step="-1" '+(page===0?'disabled':'')+'>← 上一頁</button><span aria-live="polite">第 '+(page+1)+' / '+total+' 頁</span><button id="page-next-'+key+'" data-page-key="'+key+'" data-page-step="1" '+(page===total-1?'disabled':'')+'>下一頁 →</button></nav>':'';return nav+'<div class="paged-content">'+blocks.slice(page*count,(page+1)*count).join('')+'</div>';}
function splitBlocks(html){const out=[],tag=/<\/?([a-z][\w-]*)\b[^>]*>/gi,voids=new Set(['area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr']);let depth=0,start=0,match;while((match=tag.exec(html))){const closing=match[0][1]==='/',self=voids.has(match[1].toLowerCase())||/\/\s*>$/.test(match[0]);if(!closing&&depth===0)start=match.index;if(!self)depth+=closing?-1:1;if(depth===0){out.push(html.slice(start,tag.lastIndex));start=tag.lastIndex;}}return out.length?out:[html];}
function refreshInterface(){if(overlayPage==='map')mapMenu();else if(overlayPage==='pause')pauseMenu();else if(overlayPage==='ending')ending(false);else if(overlayPage==='inventory')inventory();else if(overlayPage==='shop')shop();else if(overlayPage==='forge')forgeMenu();else if(overlayPage==='journal')journal();else if(overlayPage==='party')partyMenu();else if(overlayPage==='journey')journeyMenu();else if(overlayPage==='settings')settingsMenu();else if(overlayPage==='slots-save')slotsMenu('save');else if(overlayPage==='slots-load')slotsMenu('load');else if(overlayPage==='craft-sources')recipeSources(sourceRecipe);}
function chooseTab(value){const [kind,id]=String(value).split(':');if(!UI_TABS[kind]?.some(row=>row[0]===id)||UI_OWNERS[kind]!==overlayPage)return false;uiTabs[kind]=id;nextModalFocus='ui-tab-'+kind+'-'+id;refreshInterface();return true;}
function recipeSources(id){if(!Object.hasOwn(R.RECIPES,id))return;sourceRecipe=id;const recipe=R.RECIPES[id],rows=Object.entries(recipe.materials).map(([key,n])=>'<article class="task-card"><h3>'+R.MATERIALS[key].name+' ×'+n+'</h3><p>'+R.materialHints(key)+'</p></article>');modal(R.GEAR[id].name+'・材料線索',interfaceShell(pageBlocks('craft-sources:materials',rows,1),'<button class="primary" data-action="return-forge">返回工坊</button>'),'craft-sources');}

function durabilityText(id){const g=R.gearState(s),spec=R.GEAR[id],left=g.durability[id];return spec.durability?(left===0?'已損壞・需重鑄':'耐久 '+left+' / '+spec.durability):'空欄位';}
function gearCards(slot){const g=R.gearState(s);return g.owned.filter(id=>R.GEAR[id].slot===slot).map(id=>{const spec=R.GEAR[id],equipped=g.equipped[slot]===id,broken=id!=='none'&&g.durability[id]===0,compare=R.gearComparison(s,id),delta=compare&&!equipped?[['攻擊',compare.attack],['減傷',compare.defense]].map(([name,value])=>'<span class="'+(value>0?'stat-up':value<0?'stat-down':'')+'">'+name+' '+(value>0?'↑ +':value<0?'↓ ':'')+value+'</span>').join(' · '):'';return '<article class="gear-card '+(broken?'broken':'')+'"><h4>'+spec.name+' <small>Lv.'+spec.level+'</small>'+(equipped?' <small>裝備中</small>':'')+'</h4><p>'+spec.description+'</p><b>'+durabilityText(id)+'</b>'+(spec.durability?'<div class="durability-meter"><i style="width:'+(g.durability[id]/spec.durability*100)+'%"></i></div>':'')+'<small>'+delta+'</small><button data-gear-preview="'+id+'" '+(equipped||broken?'disabled':'')+'>能力比較</button><button data-gear-equip="'+id+'" '+(equipped||broken?'disabled':'')+'>'+(broken?'請到工坊重鑄':equipped?'已裝備':'裝備')+'</button></article>';}).join('');}
function quickItemIcon(id){if(id==='campkit')return '<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M3 27 16 5 29 27Z" fill="#c2a56e" stroke="#4c654e" stroke-width="2"/><path d="m11 27 5-13 5 13" fill="#354c3b"/></svg>';const icons={potion:['#b85848','<path d="M13 19h6m-3-3v6"/>'],highpotion:['#9d344c','<path d="M12 18h8m-4-4v8m7-14 1-3 1 3 3 1-3 1-1 3-1-3-3-1Z"/>'],tonic:['#6c9660','<path d="m18 14-5 6h5l-4 5"/>'],ether:['#668eb8','<path d="M19 14a6 6 0 1 0 1 9 6 6 0 0 1-1-9Z"/>']};if(id==='herbkit')return '<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M7 13h18v15H7Z" fill="#d7c18a" stroke="#644c34" stroke-width="1.5"/><path d="M12 13V9h8v4" fill="none" stroke="#644c34" stroke-width="2"/><path d="M16 26V16m0 6c-6 0-7-5-7-5 6-1 7 5 7 5Zm0-2c0-6 7-6 7-6 0 6-7 6-7 6Z" fill="#628655" stroke="#315b47"/></svg>';if(id==='revive')return '<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M16 30V16m0 10 8-6m-8 3-7-4" stroke="#72945e" stroke-width="2" fill="none"/><g fill="#e7c76c" stroke="#a08040"><ellipse cx="16" cy="8" rx="4" ry="6"/><ellipse cx="10" cy="12" rx="6" ry="4"/><ellipse cx="22" cy="12" rx="6" ry="4"/><ellipse cx="16" cy="16" rx="4" ry="6"/></g><circle cx="16" cy="12" r="3" fill="#f8efbb"/></svg>';const [color,symbol]=icons[id]||icons.potion;return '<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M12 5h8v7l5 6v10q-9 4-18 0V18l5-6Z" fill="#f4e7c7" stroke="#684e35" stroke-width="1.5"/><path d="M9 19q7 3 14-1v9q-7 3-14 0Z" fill="'+color+'"/><path d="M11 3h10v5H11Z" fill="#bb985b"/><g stroke="#fff8df" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round">'+symbol+'</g></svg>';}
function quickItemMarkup(){return '<h3>道具快捷欄 · 1／2／3</h3><div class="quick-item-settings">'+settings.quickItems.map((id,i)=>'<label class="form-field">快捷欄 '+(i+1)+'<select id="quick-slot-'+i+'">'+QUICK_ITEMS.map(item=>'<option value="'+item+'" '+(item===id?'selected':'')+'>'+R.ITEMS[item].name+' ×'+(s.bag[item]||0)+'</option>').join('')+'</select></label>').join('')+'</div>';}
function useQuickItem(index){if(!paused()&&Number.isInteger(index)&&index>=0&&index<3)useItem(settings.quickItems[index]);}

function statNumber(n,digits=0){return Number(n.toFixed(digits)).toLocaleString('zh-TW',{maximumFractionDigits:digits});}

function abilityMetric(stats,preview,key,label,unit='',digits=0,lowerBetter=false,limit){const before=stats[key],after=preview?.[key],changed=Number.isFinite(after)&&Math.abs(after-before)>1e-8,delta=changed?after-before:0,good=changed&&(lowerBetter?delta<0:delta>0),bar=R.abilityBar(key,before,limit),next=changed?R.abilityBar(key,after,limit):null;
 const meter=bar?'<div class="ability-meter '+(lowerBetter?'lower-is-better':'')+'" role="meter" aria-label="'+label+'的參考量尺" aria-valuemin="0" aria-valuemax="'+bar.max+'" aria-valuenow="'+Math.min(before,bar.max)+'" aria-valuetext="'+statNumber(before,digits)+unit+'，參考量尺 0 至 '+bar.max+unit+(lowerBetter?'，較低較有利':'')+'"><i class="ability-fill" style="width:'+bar.percent+'%"></i>'+(next?'<i class="ability-delta '+(good?'delta-good':'delta-bad')+'" style="left:'+Math.min(bar.percent,next.percent)+'%;width:'+Math.abs(next.percent-bar.percent)+'%"></i><i class="ability-after" style="left:clamp(1px,'+next.percent+'%,calc(100% - 2px))"></i>':'')+'</div><small class="ability-scale">量尺 0–'+statNumber(bar.max,digits)+unit+(lowerBetter?' · 越低越好':'')+(bar.overflow||next?.overflow?' · 超出量尺':'')+'</small>':'';
 return '<div class="ability-metric" data-stat="'+key+'" data-current="'+before+'"'+(changed?' data-after="'+after+'"':'')+'><dt>'+label+'</dt><dd>'+statNumber(before,digits)+unit+(changed?'<span class="stat-change '+(good?'stat-up':'stat-down')+'">→ '+statNumber(after,digits)+unit+' <small>'+(delta>0?'↑ +':'↓ ')+statNumber(delta,digits)+'</small></span>':'')+meter+'</dd></div>';}
function resourceMeter(label,value,max,tone,description=''){const percent=max>0?Math.max(0,Math.min(100,value/max*100)):100;return '<div class="resource-stat '+tone+'"><span>'+label+' <b>'+Math.ceil(value)+' / '+max+'</b></span><div class="resource-meter" role="progressbar" aria-label="'+label+'" aria-valuemin="0" aria-valuemax="'+max+'" aria-valuenow="'+Math.max(0,Math.min(value,max))+'"><i style="width:'+percent+'%"></i></div>'+(description?'<small>'+description+'</small>':'')+'</div>';}
function experienceMeter(stats){const full=stats.level>=stats.maxLevel,max=full?1:stats.nextXp,current=full?1:stats.xp,remaining=full?0:Math.max(0,max-current);return '<div class="experience-stat"><div class="experience-label"><span>升級經驗</span><b>'+(full?'已達 Lv.'+stats.maxLevel+' 上限':current+' / '+max+' EXP')+'</b></div><div class="resource-meter xp-meter" role="progressbar" aria-label="升級經驗" aria-valuemin="0" aria-valuemax="'+max+'" aria-valuenow="'+current+'" aria-valuetext="'+(full?'已達最高等級':'距離 Lv.'+(stats.level+1)+' 還需 '+remaining+' EXP')+'"><i style="width:'+(current/max*100)+'%"></i></div><small>'+(full?'無須再累積升級經驗':'距離 Lv.'+(stats.level+1)+' 還需 <b>'+remaining+' EXP</b>')+'</small></div>';}
function characterPanel(){const a=R.characterStats(s),comparison=comparisonGear&&R.compareCharacterStats(s,comparisonGear),b=comparison?.after,metric=(key,label,unit='',digits=0,lower=false)=>abilityMetric(a,b,key,label,unit,digits,lower),group=(title,content,tag='dl')=>{const id={'攻擊能力':'attack','防禦能力':'defense','機動能力':'mobility','持續作戰':'recovery','探索絕技':'techniques','法術能力':'magic'}[title];return uiTabs.ability===id?'<section class="ability-group ability-'+id+'"><h4>'+title+'</h4>'+pageBlocks('inventory:ability:'+id,splitBlocks(content).map(row=>tag==='dl'?'<dl>'+row+'</dl>':row),id==='magic'?1:uiCount(4,3))+'</section>':'';},chargeHint=a.chargeEnabled?'可使用':a.chargeLearned?'武器損壞，暫時無法使用':'尚未習得';
 return '<section id="character-panel" class="character-panel" aria-label="角色能力"><div class="character-heading"><div><p class="eyebrow">角色能力</p><h3>'+esc(a.name)+' <small>Lv.'+a.level+' / '+a.maxLevel+'</small></h3><p>'+a.gold+' G · '+(a.difficulty==='story'?'悠遊模式':'冒險模式')+' · '+(a.level>=a.maxLevel?'已達最高等級':'下一級 Lv.'+(a.level+1))+'</p></div>'+'</div>'+tabControls('ability')+(comparison?'<div class="ability-preview" role="status">預覽換裝：<b>'+esc(comparison.name)+'</b> <button data-action="inventory-equipment">返回裝備</button><button data-action="clear-comparison">取消比較</button><small>目前數值 → 換裝後數值；量條直線標記為換裝後位置，綠色區段較有利、紅色較不利。尚未換裝。</small></div>':'<p class="ability-note">目前武器：'+esc(a.weaponName)+'。到「裝備」分頁，點「能力比較」查看換裝前後差異。</p>')+(a.gear.some(g=>g.broken)?'<p class="ability-warning" role="status">'+a.gear.filter(g=>g.broken).map(g=>esc(g.name)).join('、')+'已損壞，以下顯示失效後的實際能力。</p>':'')+'<div id="ui-panel-ability" role="tabpanel" aria-labelledby="ui-tab-ability-'+uiTabs.ability+'" class="ability-grid">'+
 (uiTabs.ability==='overview'?'<div class="character-vitals">'+resourceMeter('生命',Math.ceil(a.health),a.maxHealth,'health-resource')+resourceMeter('魔力',Math.floor(a.mana),a.maxMana,'mana-resource')+resourceMeter('體力',Math.floor(a.stamina),a.maxStamina,'stamina-resource')+'</div>':'')+(uiTabs.ability==='overview'?experienceMeter(a):'')+
 group('攻擊能力',metric('attack','物理攻擊力')+metric('attackRate','基礎攻速',' 次／秒',2)+metric('attackInterval','攻擊間隔',' 秒',2,true)+metric('attackRange','攻擊範圍',' 格',2))+
 group('防禦能力',metric('defense','防禦力・固定減傷',' 點')+metric('guardReduction','舉盾減傷','%')+metric('guardCost','每次格擋消耗',' 體力',0,true)+metric('damageTakenPercent','模式承傷倍率','%',0,true))+
 group('機動能力',metric('movementPercent','一般移動速度','%')+metric('guardMovementPercent','防禦移動速度','%',1)+metric('dashPercent','衝刺速度','%',1)+metric('dashDistance','理論衝刺距離',' 格',2)+metric('dashCost','衝刺消耗',' 體力',0,true)+metric('dashCooldown','衝刺冷卻',' 秒',2,true)+metric('dashInvulnerability','衝刺無敵時間',' 秒',2))+
 group('持續作戰',metric('staminaRecovery','體力恢復','／秒',2)+metric('guardStaminaRecovery','防禦時體力恢復','／秒',2)+metric('manaRecovery','非戰鬥魔力恢復','／秒',2)+metric('manaCombatRecovery','戰鬥魔力恢復','／秒',2))+
 group('探索絕技','<div class="ability-metric"><dt>蓄力斬</dt><dd>'+chargeHint+(b&&b.chargeEnabled!==a.chargeEnabled?'<span class="stat-change '+(b.chargeEnabled?'stat-up':'stat-down')+'">→ '+(b.chargeEnabled?'可使用':'暫時無法使用')+'</span>':'')+'</dd></div>'+(a.chargeEnabled?metric('chargeDamage','蓄力基礎威力')+metric('chargeTime','蓄滿時間',' 秒',2,true)+metric('chargeCost','蓄力消耗',' 體力',0,true)+metric('chargeCooldown','重擊冷卻',' 秒',2,true)+metric('chargeMovementPercent','蓄力移動速度','%',1):'')+'<div class="ability-metric"><dt>映光防禦</dt><dd>'+(a.perfectGuardEnabled?'已習得':'尚未習得')+'</dd></div>'+(a.perfectGuardEnabled?metric('perfectGuardWindow','完美防禦時機',' 秒',2)+metric('perfectGuardMana','完美防禦回魔',' MP'):'')+'<div class="ability-metric"><dt>逐風步</dt><dd>'+(R.hasAbility(s,'trailStep')?'已習得':'尚未習得')+'</dd></div>')+
 group('法術能力',a.spells.map(skill=>'<div class="spell-stat"><h5>'+({fire:'U',heal:'I',thunder:'O'}[skill.id])+' · '+skill.name+' <small>'+(skill.enabled?'已習得':'尚未習得')+'</small></h5>'+(skill.enabled?'<dl>'+abilityMetric({spellPower:skill.power},null,'spellPower',skill.heal?'治療量':'基礎威力','',0)+abilityMetric({spellMp:skill.mp},null,'spellMp','魔力消耗',' MP',0,true,a.maxMana)+abilityMetric({spellCooldown:skill.cooldown},null,'spellCooldown','冷卻',' 秒',2,true)+'</dl>':'<p>'+({fire:'與伊娜同行後可使用。',heal:'與露米同行後可使用。',thunder:'取得林之星片後可使用。'}[skill.id])+'</p>')+'</div>').join(''),'div')+'</div><p class="ability-note">量條是參考量尺，並非能力上限。綠色較有利、紅色較不利；攻速及衝刺距離為理論值。</p></section>';}

function inventory(){const g=R.gearState(s),exploration=R.explorationSummary(s),entries=Object.entries(s.bag).filter(([,n])=>n>0);let content;if(uiTabs.inventory==='character')content=characterPanel();else if(uiTabs.inventory==='equipment'){const summary='<div class="equipment-summary">'+[['weapon','武器'],['body','身體防具'],['charm','護符']].map(([slot,label])=>'<span>'+label+'<b>'+R.GEAR[g.equipped[slot]].name+(slot==='weapon'?' +'+s.equipment.weapon:slot==='body'?' +'+s.equipment.armor:'')+'</b><small>'+durabilityText(g.equipped[slot])+'</small></span>').join('')+'</div>';content=summary+tabControls('equipment')+tabPanel('equipment','<div class="inventory-gear-pages">'+pageBlocks('inventory:equipment:'+uiTabs.equipment,splitBlocks(gearCards(uiTabs.equipment)),uiCount(2,1))+'</div>')+'<p class="interface-note">選「能力比較」查看數值取捨；選「裝備」才實際換裝。</p>';}else if(uiTabs.inventory==='items'){const cards=entries.map(([id,n])=>'<article class="inventory-item">'+(['potion','key','tonic','campkit'].includes(id)?'<img src="assets/paper/'+(id==='tonic'?'big':id)+'.svg" alt="">':'<span class="gem-icon">◆</span>')+'<div><strong>'+R.ITEMS[id].name+' ×'+n+'</strong><p>'+R.ITEMS[id].description+'</p>'+(['potion','tonic','highpotion','ether','revive','herbkit','campkit'].includes(id)?'<button data-use="'+id+'">使用</button>':'')+'</div></article>');content=quickItemMarkup()+(cards.length?pageBlocks('inventory:items',cards,uiCount(3,2)):'<p>'+(R.onboardingState(s).claimed?'行囊目前是空的。':'行囊還空著。完成青苔村的出發準備後，向阿嵐領取新手套組。')+'</p>');}else{const materials=Object.entries(R.MATERIALS).filter(([id,m])=>g.materials[id]>0||g.met.includes(m.chapter)).map(([id,m])=>'<div class="shop-row"><b>'+m.name+'</b><span>×'+g.materials[id]+'</span></div>');content='<h3>探索道具</h3><p>'+(exploration.tools.join(' · ')||'尚未找到探索道具')+'</p><p>星紋寶藏 '+exploration.treasures+' / '+exploration.total+'</p><h3>隱藏材料</h3>'+(materials.length?pageBlocks('inventory:materials',materials,uiCount(4,3)):'<p>尚未找到隱藏材料。加工線索會記入任務手札。</p>');}modal('旅人的行囊',interfaceShell(tabPanel('inventory',content),'<span class="interface-note">Z 關閉 · 分頁焦點時可用 ← → 切換</span><button class="primary" data-action="close">收起背包</button>',tabControls('inventory')),'inventory');}
function forgeMenu(){const a=R.ARTISANS[R.chapter(s)],g=R.gearState(s);let content;if(uiTabs.forge==='craft'){const cards=Object.entries(R.RECIPES).filter(([,r])=>r.chapter===R.chapter(s)).map(([id,r])=>{const spec=R.GEAR[id],status=R.craftStatus(s,id);return '<article class="gear-card"><h4>'+spec.name+' <small>Lv.'+spec.level+'</small></h4><p>'+spec.description+'</p><b>耐久 '+spec.durability+' · 加工 '+r.cost+' G</b><ul>'+Object.entries(r.materials).map(([key,n])=>'<li>'+R.MATERIALS[key].name+' '+g.materials[key]+' / '+n+'</li>').join('')+'</ul><button data-recipe-sources="'+id+'">查看材料來源</button><button data-craft="'+id+'" '+(!status.canCraft?'disabled':'')+'>'+(status.owned?'已完成':status.missing.length?'材料不足':s.gold<r.cost?'金幣不足':'交付材料並加工')+'</button>'+(status.owned?'<button data-gear-equip="'+id+'" '+(g.durability[id]===0?'disabled':'')+'>裝備</button>':'')+'</article>';});content=pageBlocks('forge:craft',cards,1);}else content='<p class="interface-note">歸零前按缺損修理；歸零後可重鑄，費用較高。</p>'+pageBlocks('forge:repair',g.owned.filter(id=>R.GEAR[id].durability).map(id=>{const q=R.repairQuote(s,id);return '<div class="shop-row"><div><b>'+R.GEAR[id].name+'</b><p>'+durabilityText(id)+'</p></div><button data-repair="'+id+'" '+(!q.cost||s.gold<q.cost?'disabled':'')+'>'+(q.cost?(q.broken?'重鑄 ':'修理 ')+q.cost+' G':'完好')+'</button></div>';}),uiCount(3,2));modal(a.workshop,interfaceShell('<p class="interface-summary">'+a.name+' · '+s.gold+' G</p>'+tabPanel('forge',content),'<button class="primary" data-action="close">離開工作臺</button>',tabControls('forge')),'forge');}
function partyMenu(){const cards=s.party.map(p=>'<article class="companion-card"><div class="companion-heading"><img src="assets/paper/person-'+p.id+'.svg" alt="" width="54" height="72"><div><h3>'+R.PARTY[p.id].name+' · '+R.PARTY[p.id].role+'</h3><p class="companion-condition">'+(p.hp<=0?'暫時倒下・需要休息或復甦補給':'正在同行')+'</p></div></div><p>生命 '+Math.ceil(p.hp)+' / '+R.PARTY[p.id].maxHp+'　魔力 '+Math.floor(p.mp)+' / '+R.PARTY[p.id].maxMp+'</p><p>'+(p.id==='ina'?'自動對可見敵人施放元素法術；與她同行後，主角能使用火花術。':'優先治療受傷隊友，必要時用聖光攻擊；與她同行後，主角能使用癒光。')+'</p></article>');modal('同行的夥伴',interfaceShell((cards.length?pageBlocks('party:members',cards,1):'<p>目前還沒有同行夥伴。青苔村的伊娜與月溪渡口的露米，也有各自想完成的旅程。</p>')+'<div class="equipment-choices"><button data-party-mode="assist" '+(s.partyMode==='assist'?'class="primary"':'')+'>輔助施法</button><button data-party-mode="hold" '+(s.partyMode==='hold'?'class="primary"':'')+'>節省魔力<small>只跟隨</small></button></div>','<button class="primary" data-action="close">繼續同行</button>'),'party');}
function journal(){const q=R.quest(s),tasks=R.taskLedger?.(s)||[],labels={accepted:'已接取',investigating:'調查中',ready:'可回報',done:'已完成'};let content;if(uiTabs.journal==='current')content='<p class="eyebrow">目前的旅程</p><h3>'+q.title+'</h3><p>'+q.text+'</p><button data-track-task="main">追蹤主線</button><p>找回星光 '+R.chapterRelicCount(s)+' / 3 · 走訪地區 '+R.regionCount(s)+' / 5</p>';else if(uiTabs.journal==='ending'){const e=R.endingState(s),cards=e.requirements.map(r=>'<article class="task-card" data-status="'+(r.done?'done':'investigating')+'"><h4>'+esc(r.title)+' '+r.count+' / '+r.total+'</h4><p>'+esc(r.hint)+'</p></article>');content='<p class="interface-summary">'+(e.finished?'目前可看：'+esc(e.title):'主線完成後，選擇與相遇會改變後日談。')+'</p>'+pageBlocks('journal:ending',cards,uiCount(2,1))+'<p class="interface-note">每章選一條分歧即可；通關後仍可回訪補齊，沒有期限。</p>'+(e.finished?'<button class="primary" data-action="ending-replay">重溫目前結局</button>':'');}else if(uiTabs.journal==='tasks')content=tasks.length?pageBlocks('journal:tasks',tasks.sort((a,b)=>(a.status==='ready'?-1:1)-(b.status==='ready'?-1:1)).map(t=>'<article class="task-card" data-status="'+t.status+'"><span class="task-status">'+labels[t.status]+'</span><h4>'+esc(t.title)+'</h4><p>'+esc(t.hint)+'</p><small>回報：'+R.MAPS[t.map].name+' · 獎勵：'+esc(t.reward)+'</small>'+(t.status!=='done'?'<button data-track-task="'+t.id+'">追蹤這項委託</button>':'')+'</article>'),uiCount(2,1)):'<p>與沿途的人交談，將值得記住的事寫進手札。</p>';else content=s.journal.length?pageBlocks('journal:log',s.journal.map(t=>'<p class="journal-entry">'+esc(t)+'</p>'),uiCount(4,3)):'<p>你的故事，才正要開始。</p>';modal('旅人手札',interfaceShell(tabPanel('journal',content),'<button class="primary" data-action="close">收起手札</button>',tabControls('journal')),'journal');}
function journeyMenu(){const report=R.journeyReport(s),labels={travel:'原野行走',reading:'閱讀與交談',puzzle:'解謎',combat:'戰鬥',town:'村鎮與房屋',menu:'整理選單',exploration:'觀察與探索'},chapters=Object.entries(report.chapters);modal('旅程回顧',interfaceShell('<p class="interface-summary">已記錄的旅程：'+timeText(report.actualMinutes*60)+'</p>'+pageBlocks('journey:chapters',chapters.map(([n,m])=>'<article class="task-card"><h3>'+R.CHAPTERS[n-1].title+'</h3>'+Object.entries(labels).map(([k,label])=>'<div class="journey-stat"><span>'+label+'</span><b>'+timeText(m[k])+'</b></div>').join('')+'<p>擊退 '+m.kills+' 隻 · 新發現 '+m.discoveries+' 處 · 完美防禦 '+m.parries+' 次</p></article>'),1),'<button data-action="export-journey">匯出旅程紀錄</button><button class="primary" data-action="close">繼續冒險</button>'),'journey');}
function exportJourney(){const url=URL.createObjectURL(new Blob([JSON.stringify(R.journeyReport(s),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='starwatch-journey-'+new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Taipei'})+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('已匯出這段旅程的紀錄。');}
function mapMenu(){const extent=R.mapSize?.(s,'overworld')||{w:24,h:16},places=R.worldKnown?.(s)||R.WORLD_LOCATIONS,icons={'村莊':'⌂','森林':'♧','渡口':'≈','遺跡':'♜','古堡':'♜'};modal(R.MAPS.overworld.name,interfaceShell('<p class="interface-note">只記錄已發現的地點；走到入口便會自動進入。</p><div class="world-chart" aria-label="已發現的原野地點">'+places.map(p=>'<button class="world-place '+(R.rootRegion(s.map)===p.id?'current':'')+'" data-map-target="'+p.id+'" style="left:'+((p.x+.5)/extent.w*100)+'%;top:'+((p.y+.5)/extent.h*100)+'%" '+(s.map!=='overworld'?'disabled':'')+'><i>'+(icons[p.kind]||'◇')+'</i><b>'+p.name+'</b><small>'+p.hint+'</small></button>').join('')+'</div><p class="interface-note">本章發現 '+places.length+' / 5 個主要地點。</p>','<button class="primary" data-action="close">收起地圖</button>'),'map');}
function slotMarkup(rec,label,action,i){if(!rec)return '<article class="slot"><div><b>'+label+'</b><p class="slot-empty">尚無旅程</p></div><button data-slot-action="'+action+'" data-slot="'+i+'" '+(action==='load'?'disabled':'')+'>'+(action==='load'?'讀取':'儲存')+'</button></article>';const a=rec.state;return '<article class="slot"><div><b>'+label+' · '+esc(a.name)+' Lv.'+a.level+'</b><p>'+R.MAPS[a.map].name+' · 星光 '+R.chapterRelicCount(a)+'/3 · '+timeText(a.playtime)+'<br>'+formatDate(rec.savedAt)+(a.flags.ending?' · 已完成故事':'')+'</p></div><button data-slot-action="'+action+'" data-slot="'+i+'">'+(action==='load'?'讀取':'儲存')+'</button></article>';}
function slotsMenu(action){const saving=action==='save',cards=[...(!saving?[slotMarkup(db.auto,'自動存檔','load','auto')]:[]),...db.slots.map((rec,i)=>slotMarkup(rec,'存檔 '+(i+1),action,i))];modal(saving?'儲存旅程':'讀取旅程',interfaceShell((!storageOK?'<p class="save-warning">瀏覽器無法儲存，請匯出存檔。</p>':'')+pageBlocks('slots-'+action+':records',cards,uiCount(2,1)),(mode==='game'&&!fallen?'<button data-action="export">匯出存檔</button>':'')+'<button data-action="import">匯入存檔</button><button data-action="'+(fallen?'death-menu':mode==='game'?'pause':'close')+'">返回</button>'),'slots-'+action);}
function confirm(title,text,action){pendingAction=action;modal(title,'<p>'+text+'</p><div class="modal-actions"><button data-action="cancel-confirm">取消</button><button class="primary" data-action="confirm">確定</button></div>','confirm');}
function settingsMenu(){const slider=(id,label,value)=>'<label class="form-field">'+label+'<input id="'+id+'" type="range" min="0" max="100" value="'+Math.round(value*100)+'" aria-label="'+label+'"></label>';let content;if(uiTabs.settings==='sound'){const rows=['<label class="form-field">全部聲音<select id="sound-setting"><option value="on" '+(settings.sound?'selected':'')+'>開啟</option><option value="off" '+(!settings.sound?'selected':'')+'>關閉</option></select></label>',slider('volume-setting','音量',settings.volume),slider('music-volume-setting','背景音樂',settings.musicVolume),slider('sfx-volume-setting','動作與提示音效',settings.sfxVolume),slider('ambient-volume-setting','環境聲',settings.ambientVolume)];content=pageBlocks('settings:sound',rows,(window.innerHeight||800)<560?3:5);}else if(uiTabs.settings==='effects')content='<label class="form-field">動態回饋（紙片動作、震動與打擊停頓）<select id="effects-setting"><option value="on" '+(settings.effects?'selected':'')+'>開啟</option><option value="off" '+(!settings.effects?'selected':'')+'>關閉</option></select></label>';else if(uiTabs.settings==='controls'){const rows=['<h3>移動與互動</h3><p>WASD／方向鍵：移動<br>空白鍵：交談、調查與推進對話（E／Enter 也可）<br>走進入口：自動切換地圖<br>也可點地面移動、點人物交談。</p>','<h3>戰鬥</h3><p>J：攻擊　K／Shift：衝刺　L：按住防禦<br>H：習得蓄力斬後按住蓄力，放開施放<br>U：火花術　I：癒光　O：雷光術<br>手機使用畫面的同名按鈕。</p>','<h3>行囊與選單</h3><p>1／2／3：使用指定道具，在道具分頁設定<br>Z：背包　X：手札　C：地圖　V：夥伴<br>同鍵關閉選單；Esc 暫停或返回<br>分頁焦點時以 ←／→ 或 Home／End 切換。</p>'];content=pageBlocks('settings:controls',rows,1);}else content='<button data-action="fullscreen">切換全螢幕</button><p>受傷可使用藥水，或回村鎮旅人泉休息。</p><p>倒下時可在星燈復活（扣一成金幣），或讀取存檔；裝備損耗保留。</p>';modal('設定與操作',interfaceShell(tabPanel('settings',content),'<button class="primary" data-action="close">完成</button>',tabControls('settings')),'settings');}
function shop(){let content;if(uiTabs.shop==='supplies'){const ids=['potion','tonic','campkit',...(R.herbStock?.(s)?['herbkit']:[]),...(R.chapter(s)>=2?['highpotion','ether']:[]),...(R.chapter(s)>=3?['revive']:[])];content=pageBlocks('shop:supplies',ids.map(id=>'<div class="shop-row"><img src="assets/paper/'+(id==='campkit'?'campkit':id==='tonic'?'big':'potion')+'.svg" alt=""><div><b>'+R.ITEMS[id].name+'</b><p>'+R.ITEMS[id].description+'　持有 '+s.bag[id]+'</p></div><button data-buy="'+id+'" '+(s.gold<R.ITEMS[id].price?'disabled':'')+'>'+R.ITEMS[id].price+' G 購買</button></div>'),uiCount(3,2));}else if(uiTabs.shop==='gear'){const legacy={spear:45,axe:60,ward:35},rows=Object.entries(R.GEAR).filter(([id,spec])=>spec.slot===uiTabs.shopgear&&spec.chapter<=R.chapter(s)&&(spec.price||legacy[id])).map(([id,spec])=>{const owned=R.gearState(s).owned.includes(id),price=spec.price||legacy[id];return '<div class="shop-row"><div><b>'+spec.name+' · Lv.'+spec.level+'</b><p>'+spec.description+' 耐久 '+spec.durability+'</p></div><button '+(legacy[id]?'data-purchase':'data-buy-gear')+'="'+id+'" '+(owned||s.gold<price?'disabled':'')+'>'+(owned?'已持有':price+' G 購買')+'</button></div>';});content=tabControls('shopgear')+tabPanel('shopgear',pageBlocks('shop:gear:'+uiTabs.shopgear,rows,uiCount(2,1)));}else content=pageBlocks('shop:upgrades',['weapon','armor'].map(type=>{const tier=s.equipment[type],price=R.upgradePrice(s,type);return '<div class="shop-row"><span class="equipment-icon">'+(type==='weapon'?'⚔':'◇')+'</span><div><b>'+(type==='weapon'?'武器強化':'護甲強化')+' +'+tier+'</b><p>'+(type==='weapon'?'每次強化，攻擊增加 8。':'每次強化，受到的傷害減少 2。')+'</p></div><button data-upgrade="'+type+'" '+(tier>=R.upgradeCap(s)||s.gold<price?'disabled':'')+'>'+(tier>=R.upgradeCap(s)?'已達最高強化':price+' G 強化')+'</button></div>';}),uiCount(2,1));modal('米菈的旅行小舖',interfaceShell('<p class="interface-summary">金幣：<b>'+s.gold+' G</b></p>'+tabPanel('shop',content),'<button class="primary" data-action="close">結束交易</button>',tabControls('shop')),'shop');}
function chapterEnding(n){save();modal(R.CHAPTERS[n-1].title+'・完成','<p class="eyebrow">CHAPTER '+n+' COMPLETE</p><div class="story-illustration">✦</div>'+[...R.CHAPTERS[n-1].outro,...R.branchEpilogue(s,n)].map(t=>'<p>'+esc(t)+'</p>').join('')+'<p>本章遊戲時間：'+timeText(R.journeyReport?Object.values(R.journeyReport(s).chapters[n]||{}).filter((v,i)=>i<7).reduce((a,b)=>a+b,0):s.campaign.times[n]||0)+'。已自動儲存，可以先休息，也能繼續旅行。</p><div class="modal-actions"><button data-action="close">暫留本章</button><button class="primary" data-next-chapter="'+(n+1)+'">前往下一章 →</button></div>','chapter-ending');}
function chapterTravelMenu(){modal('星舟的航線','<p>可以前往已開放的章節，保留角色、夥伴與探索進度。</p><div class="menu-grid">'+R.CHAPTERS.map(c=>'<button data-next-chapter="'+c.id+'" '+(c.id>1&&!s.campaign.finished.includes(c.id-1)?'disabled':'')+'>'+c.title+'<small>建議 Lv.'+c.levels.join('～')+'</small></button>').join('')+'</div><div class="modal-actions"><button data-action="close">返回</button></div>','chapter-travel');}
function handoverBoard(b){const names=R.HANDOVER_PILLARS,description=b.towers.map((a,i)=>names[i]+'，由下往上：'+(a.join('、')||'空柱')).join('；'),colors=['','#efd58b','#94b7a3','#7c9fb7','#b29aba'];let svg='<svg viewBox="0 0 420 195" role="img" aria-label="'+esc(description)+'"><rect x="5" y="6" width="410" height="181" rx="12" fill="#f8f1d9"/>';b.towers.forEach((a,i)=>{const x=70+i*140;svg+='<path d="M'+(x-49)+' 157h98l-6 9h-86Z" fill="#b8a179" stroke="#36513d" stroke-width="2"/><path d="M'+(x-4)+' 151V43h8v108" fill="#d7c49a" stroke="#36513d" stroke-width="2"/>';a.forEach((disk,j)=>{const w=28+disk*19,y=140-j*20;svg+='<path d="M'+(x-w/2)+' '+y+'l7 -6h'+(w-14)+'l7 6v12h-'+w+'Z" fill="'+colors[disk]+'" stroke="#fff8df" stroke-width="6"/><path d="M'+(x-w/2)+' '+y+'h'+w+'v12h-'+w+'Z" fill="'+colors[disk]+'" stroke="#263e33" stroke-width="2"/><path d="M'+(x-w/2+4)+' '+(y+2)+'h'+(w-8)+'" stroke="#fff8df" stroke-width="1.5"/><text x="'+x+'" y="'+(y+10)+'" text-anchor="middle" font-size="11" fill="#263e33">'+disk+'</text>';});svg+='<text x="'+x+'" y="183" text-anchor="middle" font-size="13" fill="#263e33">'+names[i]+(b.selected===i?'・已選':'')+'</text>';});return '<figure class="handover-board"><figcaption>'+esc(b.caption)+'</figcaption>'+svg+'</svg><p>'+esc(description)+'</p></figure>';}
function shelterBoard(b){const wires=b.inputs.map((p,i)=>{const x=b.inputs.length===1?150:80+i*140;return '<g><path d="M'+x+' 70 L150 108" stroke="#a38a61" stroke-width="3"/><rect x="'+(x-61)+'" y="12" width="122" height="60" rx="5" fill="'+(p.on?'#efd58b':'#e6e4d5')+'" stroke="#263e33" stroke-width="3"/><text x="'+x+'" y="37" text-anchor="middle">'+esc(p.name)+'</text><text x="'+x+'" y="58" text-anchor="middle">'+(p.on?'有':'無')+'</text></g>'}).join('');return '<figure class="story-board shelter-board"><figcaption>'+esc(b.caption)+'</figcaption><svg viewBox="0 0 300 168" role="img" aria-label="'+esc(b.inputs.map(p=>p.name+'：'+(p.on?'有':'無')).join('，')+'；'+b.result+'：'+(b.lit?'是':'否'))+'">'+wires+'<rect x="45" y="106" width="210" height="48" rx="5" fill="'+(b.lit?'#efd58b':'#e6e4d5')+'" stroke="#263e33" stroke-width="3"/><text x="150" y="136" text-anchor="middle">'+esc(b.result)+'：'+(b.lit?'是':'否')+'</text></svg><ol>'+b.combos.map(c=>'<li class="story-cell '+(c.active?'active':c.seen?'fixed':'muted')+'">'+(c.seen?'✓ ':'○ ')+esc(c.label)+'</li>').join('')+'</ol><p>✓ 已測試　○ 待測試；框線表示目前狀態</p></figure>';}
function runeRepairBoard(b){const names=R.GUARDIAN_COMMANDS,pos=(x,y)=>[(x-8)*44+40,(y-4)*35+12];let svg='<svg viewBox="0 0 350 206" role="img" aria-label="'+esc('試行紙模：'+b.progress)+'">';for(const [x,y]of R.GUARDIAN_TRACK){const [px,py]=pos(x,y);svg+='<rect x="'+px+'" y="'+py+'" width="40" height="31" rx="3" fill="'+(x===13&&y===5?'#efd58b':'#e3eddf')+'" stroke="#315b47" stroke-width="2"/>';}let [rx,ry]=pos(...b.frame.rock);svg+='<path d="M'+(rx+9)+' '+(ry+24)+'l-3 -15 12 -7 13 8 -2 14Z" fill="#a38a61" stroke="#263e33" stroke-width="2"/>';const [sx,sy]=pos(b.frame.x,b.frame.y);svg+='<rect x="'+(sx+8)+'" y="'+(sy+3)+'" width="25" height="25" rx="4" fill="#fff8df" stroke="#263e33" stroke-width="3"/><text x="'+(sx+20)+'" y="'+(sy+23)+'" text-anchor="middle" font-size="20">'+['→','↓','←','↑'][b.frame.dir]+'</text><text x="40" y="200" font-size="12">起點朝東 → 沿石道推石 → 東北踏板</text></svg>';return '<figure class="story-board rune-repair-board"><figcaption>'+esc(b.caption)+'</figcaption>'+svg+'<p class="rune-progress" aria-live="polite">'+esc(b.progress)+'</p><ol class="rune-cards">'+b.plan.map((cmd,i)=>'<li><button data-choice="pick-'+i+'" data-choice-room="rune-repair-plan" aria-pressed="'+(b.selected===i)+'" class="rune-card '+(b.selected===i?'selected ':'')+(b.index===i?'current ':'')+''+'"><b>'+String(i+1).padStart(2,'0')+'</b><span>'+esc(names[cmd])+'</span></button></li>').join('')+'</ol>'+(b.plan.length?'':'<p>副本空白，可追加新的符石。</p>')+'</figure>';}
function continuingRouteBoard(b){const max=Math.max(4,b.position,...b.lamps),width=(max+1)*48+16;let svg='<svg viewBox="0 0 '+width+' 100" role="img" aria-label="'+esc(b.status)+'">';for(let i=0;i<=max;i++){const x=8+i*48;svg+='<path d="M'+x+' 67h42v20h-42Z" fill="#c7b48c" stroke="#263e33" stroke-width="2"/>';if(b.goal===i)svg+='<path d="M'+(x+37)+' 18v40m0 -40 13 7 -13 7" fill="#efd58b" stroke="#263e33" stroke-width="2"/>';if(b.lamps.includes(i))svg+='<path d="M'+(x+21)+' 24l10 18 -10 17 -10 -17Z" fill="#efd58b" stroke="#263e33" stroke-width="2"/>';svg+='<text x="'+(x+21)+'" y="82" text-anchor="middle" font-size="11">'+i+'</text>';if(b.position===i)svg+='<path d="M'+(x+10)+' 4h22v22h-22Z" fill="#fff8df" stroke="#263e33" stroke-width="3"/><text x="'+(x+21)+'" y="21" text-anchor="middle" font-size="15">→</text>';}svg+='</svg>';return '<figure class="story-board continuing-board"><figcaption>'+esc(b.caption)+'</figcaption>'+svg+'<p class="continuing-status" aria-live="polite">'+esc(b.status)+'</p><p>'+esc(b.footer)+'</p><ol>'+b.checks.map(c=>'<li class="story-cell '+c.state+'">'+esc(c.text)+'</li>').join('')+'</ol></figure>';}
function choiceBoard(board){if(board?.kind==='continuing-route')return continuingRouteBoard(board);if(board?.kind==='rune-repair')return runeRepairBoard(board);if(!board)return '';if(board.kind==='shelter')return shelterBoard(board);if(board.kind==='handover')return handoverBoard(board);return '<figure class="story-board"><figcaption>'+esc(board.caption)+'</figcaption><ol>'+board.cells.map(cell=>'<li class="story-cell '+(['active','fixed','muted'].includes(cell.state)?cell.state:'')+'">'+esc(cell.text)+'</li>').join('')+'</ol><p>框線：本次核對　綠格：已確認　暗格：已排除</p></figure>';}
function choiceMenu(choice){if(choice.board?.kind==='continuing-route'){const primary=choice.options.filter(o=>['run','step','finish','stop','next','call'].includes(o.id)),other=choice.options.filter(o=>!primary.includes(o)),button=o=>'<button data-choice="'+o.id+'" data-choice-room="'+choice.id+'">'+esc(o.text)+'</button>',input=choice.input?'<label class="continuing-name">'+esc(choice.input.label)+'<input id="continuing-name" maxlength="'+choice.input.max+'" value="'+esc(choice.input.value)+'" autocomplete="off"></label>':'';modal(choice.title,'<p class="handover-status">'+esc(choice.summary)+'</p>'+choiceBoard(choice.board)+'<div class="modal-actions">'+primary.map(button).join('')+'</div>'+(other.length?'<details class="continuing-controls" open><summary>安排動作與本次巡路</summary>'+input+'<div class="modal-actions">'+other.map(button).join('')+'</div></details>':'')+'<details class="handover-instructions"><summary>故事與試行說明</summary><p class="story-page">'+esc(choice.text)+'</p></details>','choice');return;}if(choice.board?.kind==='rune-repair'){modal(choice.title,'<div class="rune-repair-choice"><p class="handover-status" aria-live="polite">'+esc(choice.summary)+'</p>'+choiceBoard(choice.board)+'<div class="modal-actions">'+choice.options.map(o=>'<button data-choice="'+o.id+'" data-choice-room="'+choice.id+'">'+esc(o.text)+'</button>').join('')+'</div><details class="handover-instructions"><summary>巡路副本與修繕說明</summary><p class="story-page">'+esc(choice.text)+'</p></details></div>','choice');return;}if(choice.board?.kind==='shelter'){modal(choice.title,'<div class="shelter-choice"><p class="handover-status">'+esc(choice.summary)+'</p>'+choiceBoard(choice.board)+'<div class="modal-actions">'+choice.options.map(o=>'<button data-choice="'+o.id+'" data-choice-room="'+choice.id+'">'+esc(o.text)+'</button>').join('')+'</div><details class="handover-instructions"><summary>修繕方法與試驗說明</summary><p class="story-page">'+esc(choice.text)+'</p></details></div>','choice');return;}if(choice.board?.kind==='handover'){const buttons=choice.options.map(o=>'<button data-choice="'+o.id+'" data-choice-room="'+choice.id+'">'+o.text+'</button>').join('');modal(choice.title,'<div class="handover-choice"><p class="handover-status">'+esc(choice.summary)+'</p>'+choiceBoard(choice.board)+'<div class="modal-actions">'+buttons+'</div><details class="handover-instructions"><summary>交班提示與完整規則</summary><p class="story-page">'+esc(choice.text)+'</p></details></div>','choice');return;}modal(choice.title,'<p class="story-page">'+esc(choice.text)+'</p>'+choiceBoard(choice.board)+'<div class="modal-actions">'+choice.options.map(o=>'<button data-choice="'+o.id+'" data-choice-room="'+choice.id+'">'+o.text+'</button>').join('')+'</div>','choice');}
function ending(present=true){const outcome=present?R.recordEnding(s):R.endingState(s);if(!outcome?.finished){notify('先完成三章主線，再回來重溫結局。');return;}if(present){save();tone(659,.7,'sine',.18);}const blocks=outcome.pages.map(p=>'<article class="story-page"><h3>'+esc(p.title)+'</h3>'+p.lines.map(t=>'<p>'+esc(t)+'</p>').join('')+'</article>');modal(outcome.title,interfaceShell('<p class="eyebrow">三章旅程完成 · '+(outcome.kind==='hidden'?'HIDDEN ENDING':'THE LIGHT RETURNS')+'</p><p class="interface-summary">Lv.'+s.level+' / 30 · 旅途時間 '+timeText(R.journeyReport?R.journeyReport(s).actualMinutes*60:s.playtime)+' · 已自動儲存</p>'+pageBlocks('ending:'+outcome.kind,blocks,1),'<button data-action="ending-clues">查看結局線索</button><button data-action="save">手動儲存</button><button class="primary" data-action="close">繼續探索 →</button>'),'ending');}
function exportSave(){const payload=JSON.stringify({game:'paper-rpg-starwatch',version:2,savedAt:Date.now(),state:s},null,2),url=URL.createObjectURL(new Blob([payload],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='paper-rpg-'+new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Taipei'})+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('已匯出存檔。請妥善保留下載的 JSON 檔案。');}
$('save-import').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>300000)throw Error('存檔檔案過大。');const raw=JSON.parse(await file.text()),state=R.validate(raw.state||raw);confirm('匯入這段旅程？',esc(state.name)+' · '+R.MAPS[state.map].name+' · Lv.'+state.level+'。載入後會更新自動存檔，手動欄位會保留。',()=>{start(state);save();notify('已匯入旅程。');});}catch(err){modal('無法匯入存檔','<p class="error-note">'+esc(err.message||'檔案格式不正確。')+'</p><div class="modal-actions"><button data-action="load-title">返回存檔</button></div>','import-error');}};
async function transition(info){R.syncWildlife(s,rt.mobs,rt.map||s.map);rt.transition=true;clearInput();if(info?.from){rt.travelView={...s,...info.from};const camera=renderer.cam;if(camera){canvas.style.transformOrigin=((info.from.x-camera.x)*camera.z)+'px '+((info.from.y-camera.y)*camera.z)+'px';}canvas.classList.add(info.entering?'map-zoom-in':'map-zoom-out');}$('fade').classList.add('active');await new Promise(ok=>setTimeout(ok,380));rt=runtime();rt.map=s.map;rt.mobs=R.enemies(s);R.ensurePopulation(s,rt.mobs);R.placeParty(s);canvas.classList.remove('map-zoom-in','map-zoom-out');renderer.resize();updateHud();save();announce();$('fade').classList.remove('active');}
function interact(){if(paused())return;const o=R.nearest(s);if(!o){notify('附近沒有可調查的事物。');return;}if(o.type==='star-lamp'&&rt.mobs.some(e=>e.hp>0&&R.dist(s,e)<200)){notify('附近仍有敵人，先脫離戰鬥再點亮星燈。');return;}const before=JSON.stringify(s.flags),r=R.interact(s,o.id);rt.path=[];rt.target=null;if(r.checkpoint){updateHud();checkpointMenu(r.text);return;}if(r.transition){transition(r);return;}if(r.shop){shop();return;}if(r.crafting){save();forgeMenu();return;}if(r.choice){choiceMenu(r.choice);return;}if(r.chapterTravel){chapterTravelMenu();return;}if(r.chapterEnd){chapterEnding(r.chapterEnd);return;}if(r.ending){ending();return;}updateHud();if(r.loot){notify(r.toast?r.text+'\n'+r.toast:r.text);tone(784,.15,'sine',.15);save();return;}if(r.important||r.heal||before!==JSON.stringify(s.flags))save();if(r.lines||r.speaker)dialogue(r.speaker,r.lines||r.text,()=>{if(r.companionTalk&&R.finishCompanionTalk(s,r.companionTalk)){notify(R.PARTY[r.companionTalk].name+'加入了隊伍。');updateHud();save();}if(r.onboardingTalk){const result=R.finishOnboardingTalk(s,r.onboardingTalk);if(result){notify(result.text);updateHud();save();}}if(r.toast)notify(r.toast);},o);else notify(r.toast||r.text);}
function useItem(id){if(mode!=='game'||fallen)return;const r=id==='campkit'?R.camp(s,rt.mobs):R.use(s,id);notify(r.text);if(r.camped){rt.path=[];rt.target=null;rt.projectiles=[];save();}if(r.ok){R.recordJourneyEvent?.(s,'heals');tone(610,.2,'sine',.12);updateHud();if(overlayPage==='inventory')inventory();}}
function damageEnemy(e,amount,element='physical',charged=false){if(e.hp<=0||e.spawnIn>0)return false;const result=R.combatDamage?R.combatDamage(s,e,amount,element,s,charged):R.elementDamage(s,e,amount,element);if(result.evaded){rt.fx.push({x:e.x,y:e.y-55,text:'影化',life:.7,color:'#d7e0d5'});return false;}e.hp-=result.damage;e.hit=.17;if(result.damage>0)paperEffect(element==='fire'?'flame':element==='thunder'?'bolt':'impact',e.x,e.y-25);if(element==='physical'){tone(result.blocked?180:charged?310:520,charged?.16:.055,result.blocked?'square':'triangle',result.blocked?.08:.11);if(settings.effects){rt.hitstop=charged?.065:.028;rt.shake=charged?2.4:1;}}rt.fx.push({x:e.x,y:e.y-60,text:(result.blocked?'格擋 ':result.weak?'弱點！ ':'')+'-'+result.damage,life:1,color:result.weak?'#ffdf88':'#fff1c2'});if(e.hp<=0)defeat(e);return result.damage>0;}
function attack(charged=false){if(R.isCampSafe(s)){if(!paused())notify('營地內請安心休息；離開守護光圈後才能攻擊。');return;}if(!charged&&keys.has('charge'))return;if(paused()||rt.attackCd>0||keys.has('guard'))return;if(charged&&(!R.hasAbility(s,'chargedBlade')||s.stamina<RULES.chargeCost||R.weaponProfile(s).broken))return;const weapon=R.weaponProfile(s),range=weapon.range+(charged?RULES.chargeRange:0);rt.path=[];rt.target=null;rt.attack=charged?.34:.22;rt.chargedAttack=charged;rt.attackCd=charged?RULES.chargeCooldown:weapon.cooldown;if(charged)s.stamina-=RULES.chargeCost;tone(charged?270:190,charged?.18:.08,'triangle',.1);const harvest=!weapon.broken&&R.strikeEnvironment?.(s);if(harvest)notify(harvest);const practice=R.practiceStrike?.(s);if(practice){notify(practice.text);rt.fx.push({x:R.center(12),y:R.center(8)-50,text:'練習命中',life:.7,color:'#efdaa3'});}let connected=!!harvest||!!practice,bossFelled=false;for(const e of rt.mobs){if(e.hp<=0||e.spawnIn>0)continue;const d=R.dist(s,e),dot=((e.x-s.x)*s.facing.x+(e.y-s.y)*s.facing.y)/(d||1);if(d<range&&dot>(charged?-.8:weapon.family==='spear'?.55:weapon.family==='axe'?-.6:-.25)&&R.lineOfSight(s,s,e)){const hit=damageEnemy(e,Math.round(R.attackPower(s)*(charged?RULES.chargeMultiplier:1)),'physical',charged);connected=hit||connected;if(hit&&e.hp<=0&&R.ENEMIES[e.type].boss)bossFelled=true;if(hit&&e.hp>0){const push=charged?28:weapon.family==='axe'?20:10,dx=(e.x-s.x)/(d||1)*push,dy=(e.y-s.y)/(d||1)*push;if(R.walkable(s,e.x+dx,e.y+dy)){e.x+=dx;e.y+=dy;}}}}if(connected){wearEquipment('weapon',charged?2:1);if(bossFelled||practice?.progress){updateHud();save();}}}
function beginCharge(){if(paused()||!R.hasAbility(s,'chargedBlade'))return;if(R.weaponProfile(s).broken){notify('武器已損壞，請先修理或更換。');return;}keys.delete('attack');keys.add('charge');rt.charge=0;rt.path=[];rt.target=null;}
function releaseCharge(cancel=false){const ready=rt.charge>=RULES.chargeTime;keys.delete('charge');rt.charge=0;if(!cancel&&ready&&!paused())attack(true);}
function cast(id){if(id!=='heal'&&R.isCampSafe(s)){notify('離開營地守護光圈後才能施放攻擊法術。');return;}if(paused()||!R.castAvailable(s,id))return;const skill=R.SKILLS[id];if(rt.skillCd[id]>0)return;if(s.mp<skill.mp){notify('魔力不足。使用星露，或回村休息。');return;}if(id==='heal'){const target=s.hp<s.maxHp?s:s.party.find(p=>p.hp>0&&p.hp<R.PARTY[p.id].maxHp);if(!target){notify('隊伍目前不需要治療。');return;}target.hp=Math.min(target===s?s.maxHp:R.PARTY[target.id].maxHp,target.hp+skill.heal);paperEffect('flower',target.x,target.y-18);rt.fx.push({x:target.x,y:target.y-50,text:'+'+skill.heal,life:1,color:'#dceebc'});}else{const enemy=rt.mobs.filter(e=>e.hp>0&&!e.spawnIn&&R.dist(s,e)<340&&R.lineOfSight(s,s,e)).sort((a,b)=>R.dist(s,a)-R.dist(s,b))[0];if(!enemy){notify('視線內沒有法術目標。');return;}rt.magic.push({x:s.x,y:s.y,tx:enemy.x,ty:enemy.y,element:skill.element,life:.32});damageEnemy(enemy,skill.damage+(s.level-1)*RULES.spellGrowth,skill.element);}s.mp-=skill.mp;wearEquipment('spell');rt.skillCd[id]=skill.cooldown;tone(id==='heal'?680:490,.18,'sine',.12);updateHud();}
function defeat(e){if(!R.markDefeated(s,e))return;paperEffect('burst',e.x,e.y-25);R.journeyDefeat?.(s,e);const spec=R.ENEMIES[e.type],reward=R.awardEnemy(s,e),up=reward.up;rt.fx.push({x:e.x,y:e.y-30,text:(reward.xp?'+'+reward.xp+' EXP · ':'')+'+'+reward.gold+' G',life:1.2,color:'#e5d295'});if(up){notify('升到 Lv.'+s.level+'，生命與魔力恢復！');tone(880,.3,'sine',.16);}if(spec.boss){soundtrack.cue('victory');rt.projectiles=[];if(R.chapter(s)>1){s.bag.highpotion++;s.bag.ether++;}else{s.bag.potion++;s.bag.tonic++;}if(e.id==='warden'){s.flags.boss=true;R.log(s,'讓失落的守燈者恢復平靜。');dialogue('恢復神智的守燈者',['你把星光帶回來了……原來，我一直守著的不是這座空城。','是所有還在路上的人。去吧，替我把燈點亮。'],()=>{save();notify('走向古堡深處，點亮星燈核心。');});}else{const lines=R.victoryText(s,e)||(e.type==='treant'?['陰影從根部散去，巨靈低下頭，讓出通往林之星匣的路。',s.party.some(p=>p.id==='ina')?'伊娜望著重新發光的枝葉，輕聲說：「這次，我終於幫上忙了。」':'根燈重新亮起。回到青苔村，把巨靈恢復平靜的消息告訴伊娜。']:e.type==='tideLord'?['濁流退去，石壁後重新湧出清澈的溪水。','渡口的水與藥草，都能慢慢恢復了。溪之星匣就在前方。']:['錯亂的鐘聲終於停息，月、星與日的回音合成一段完整旋律。','守塔人的約定仍留在鐘樓裡，塔之星匣重新亮起。']);R.log(s,'解救了'+spec.name+'。');dialogue(spec.name,lines,()=>save());}save();}else R.log(s,'擊退'+spec.name+'，獲得 '+reward.xp+' 經驗與 '+reward.gold+' 枚金幣。');updateHud();}
function dash(){if(paused()||rt.dashCd>0||s.stamina<(R.dashCost?.(s)||24))return;rt.dash=RULES.dashDuration;rt.dashCd=R.dashCooldown?.(s)||.75;rt.invuln=Math.max(rt.invuln,RULES.dashInvulnerability);s.stamina-=R.dashCost?.(s)||24;paperEffect('dash',s.x,s.y-15,{angle:Math.atan2(s.facing.y,s.facing.x)});const practice=R.practiceAction?.(s,'dash');if(practice){notify(practice);updateHud();save();}tone(240,.09,'triangle',.07);}
function hurt(damage){if(R.isCampSafe(s))return;damage*=R.nightMultiplier(s);if(rt.invuln>0||rt.transition||paused())return;const blocking=keys.has('guard')&&s.stamina>=RULES.guardCost;if(blocking&&R.hasAbility?.(s,'pulseGuard')&&rt.guardAge<=RULES.perfectWindow&&!rt.guardPerfectUsed){rt.guardPerfectUsed=true;paperEffect('shield',s.x,s.y-28);s.stamina-=RULES.guardCost;s.mp=Math.min(R.maxMp(s),s.mp+RULES.perfectMana);wearEquipment('body');rt.invuln=.4;for(const e of rt.mobs)if(e.hp>0&&!R.ENEMIES[e.type].boss&&R.dist(e,s)<110)e.stagger=.5;rt.fx.push({x:s.x,y:s.y-70,text:'完美防禦',life:1,color:'#f5e4a5'});R.recordJourneyEvent?.(s,'parries');tone(820,.16,'sine',.15);return;}if(blocking)s.stamina-=RULES.guardCost;const amount=R.receivedDamage(s,blocking?damage*RULES.guardMultiplier:damage);s.hp=Math.max(0,s.hp-amount);if(settings.effects)rt.paperHurt=.72;paperEffect(blocking?'shield':'impact',s.x,s.y-28);wearEquipment('body');R.recordJourneyEvent?.(s,'damage',amount);if(settings.effects)rt.shake=3;rt.invuln=.85;rt.fx.push({x:s.x,y:s.y-70,text:'-'+amount,life:1,color:'#ffd7c0'});tone(110,.1,'triangle',.16);updateHud();if(s.hp===0)fall();}
function updateHud(){const q=R.trackedQuest?.(s)||R.quest(s);$('player-name').textContent=s.name;$('level').textContent='Lv.'+s.level+' / '+R.MAX_LEVEL;$('hp-fill').style.width=(s.hp/s.maxHp*100)+'%';$('hp-text').textContent=Math.ceil(s.hp)+' / '+s.maxHp;$('stamina-fill').style.width=s.stamina+'%';$('xp-fill').style.width=(s.level>=R.MAX_LEVEL?1:s.xp/R.xpToNext(s.level))*100+'%';$('region-name').textContent=R.MAPS[s.map].name;$('region-sub').textContent='第'+R.chapter(s)+'章 · Lv.'+(R.MAPS[s.map].recommended||[1,30]).join('～')+' · '+R.dayClock(s).label+(R.isCampSafe(s)?' · 營地安全區':R.nightMultiplier(s)>1?' · 危險 ×'+R.nightMultiplier(s):'');$('gold').textContent=s.gold+' G';for(let i=0;i<3;i++){const id=settings.quickItems[i],count=s.bag[id]||0,button=$('quick-item-'+i);$('quick-icon-'+i).innerHTML=count?quickItemIcon(id):'';$('quick-name-'+i).textContent=count?R.ITEMS[id].name:'空';button.title=count?R.ITEMS[id].name+'：'+R.ITEMS[id].description+'（背包 Z → 道具可更換）':'空欄位：獲得道具後會顯示，背包 Z 的道具分頁可更換配置。';$('quick-count-'+i).textContent=count||'';button.disabled=count===0;button.setAttribute('aria-label','快捷欄 '+(i+1)+'：'+(count?R.ITEMS[id].name+'，剩餘 '+count:'空欄位'));}$('quest-title').textContent=q.title;$('quest-text').textContent=q.text;$('mp-fill').style.width=(s.mp/R.maxMp(s)*100)+'%';$('mp-text').textContent=Math.floor(s.mp)+' / '+R.maxMp(s);const gear=R.gearState(s);$('gear-status').textContent=[['weapon','武'],['body','甲'],['charm','符']].map(([slot,label])=>{const id=gear.equipped[slot];return label+' '+(id==='none'?'—':gear.durability[id]===0?'損壞':gear.durability[id]+'/'+R.GEAR[id].durability);}).join(' · ');$('gear-status').classList.toggle('danger',Object.values(gear.equipped).some(id=>id!=='none'&&gear.durability[id]<=R.GEAR[id].durability*.2));$('population-count').textContent=R.isCampSafe(s)?'夜間營地・安全':R.wildernessStatus?.(s,rt.mobs)||(R.SPAWN_RULES[s.map]?'野怪 '+rt.mobs.filter(e=>e.hp>0).length+'/'+R.SPAWN_RULES[s.map].cap:R.MAPS[s.map].theme==='village'?'安全區・無怪':'迷宮');$('party-hud').innerHTML=s.party.map(p=>'<div class="party-mini '+(p.hp<=0?'fallen':'')+'"><img src="assets/paper/person-'+p.id+'.svg" alt="" width="28" height="38"><div class="party-mini-copy"><b>'+R.PARTY[p.id].name+' <small>'+R.PARTY[p.id].role+'</small></b><span>'+(p.hp<=0?'暫時倒下':('HP '+Math.ceil(p.hp)+' / '+R.PARTY[p.id].maxHp+'　MP '+Math.floor(p.mp)))+'</span></div></div>').join('');for(const [id,skill]of Object.entries(R.SKILLS)){const available=R.castAvailable(s,id),cd=rt.skillCd[id]||0;$('skill-'+id).textContent=!available?'未習得':cd>0?cd.toFixed(1)+'s':skill.mp+' MP';document.querySelector('[data-skill="'+id+'"]').disabled=!available;}const boss=rt.mobs.find(e=>R.ENEMIES[e.type].boss&&e.hp>0);$('boss-hud').hidden=!boss||(boss.id==='warden'&&!s.flags.seal)||R.dist(s,boss)>420;if(boss)$('boss-name').textContent=R.ENEMIES[boss.type].name;if(boss)$('boss-fill').style.width=boss.hp/boss.maxHp*100+'%';renderer.minimap?.(s,$('minimap'),rt.mobs);$('overworld-hint').hidden=s.map!=='overworld';$('charge-button').disabled=!R.hasAbility?.(s,'chargedBlade');$('charge-status').textContent=R.hasAbility?.(s,'chargedBlade')?(rt.charge>0?Math.round(Math.min(1,rt.charge/RULES.chargeTime)*100)+'%':'按住蓄力'):'未習得';}
function partyHurt(target,damage){if(R.isCampSafe(s,target))return;if(target===s){hurt(damage);return;}if(target.hp<=0||target.invuln>0||paused())return;damage*=R.nightMultiplier(s);const amount=Math.max(1,Math.round(damage*(s.difficulty==='story'?.4:.8)));target.hp=Math.max(0,target.hp-amount);target.invuln=.8;paperEffect('impact',target.x,target.y-25);rt.fx.push({x:target.x,y:target.y-50,text:'-'+amount,life:1,color:'#f1c8ae'});if(target.hp===0)notify(R.PARTY[target.id].name+'暫時無法戰鬥。回旅人泉休息可恢復。');}
function enemyUpdate(dt){for(const p of s.party)p.invuln=Math.max(0,(p.invuln||0)-dt);for(const e of rt.mobs){if(e.hp<=0)continue;e.hit=Math.max(0,e.hit-dt);if(e.spawnIn>0){e.spawnIn=Math.max(0,e.spawnIn-dt);continue;}e.cooldown=Math.max(0,e.cooldown-dt);if(e.id==='warden'&&!s.flags.seal)continue;const spec=R.ENEMIES[e.type],targets=[s,...s.party.filter(p=>p.hp>0)].filter(p=>!R.isCampSafe(s,p));if(!targets.length){e.windup=0;e.tech=null;if(e.nightVariant)R.stepEnemyMind(s,e,[],dt);continue;}const mind=R.stepEnemyMind?.(s,e,targets,dt);if(mind?.warning)tone(mind.warning==='slime'?280:mind.warning==='guard'?170:630,.09,'triangle',.07);for(const event of mind?.events||[]){if(event.kind==='hit')partyHurt(event.target,event.damage);if(event.kind==='projectile')rt.projectiles.push(event);}if(mind?.handled)continue;const target=mind?.target||targets.sort((a,b)=>R.dist(a,e)-R.dist(b,e))[0],d=R.dist(target,e);if(e.windup>0){e.windup-=dt;if(e.windup<=0){if(spec.boss){for(const p of targets)if(R.dist(p,e)<112)partyHurt(p,spec.damage+5);if(spec.pattern!=='stomp'&&e.type!=='treant'){const count=e.id==='warden'&&e.hp<e.maxHp*.5?12:8;for(let n=0;n<count;n++){const a=spec.pattern==='fan'?Math.atan2(target.y-e.y,target.x-e.x)+(n-(count-1)/2)*.16:n*Math.PI*2/count+e.phase*.21;rt.projectiles.push({x:e.x,y:e.y,vx:Math.cos(a)*102,vy:Math.sin(a)*102,life:4});}}e.phase++;e.cooldown=e.id==='warden'&&e.hp<e.maxHp*.5?1.6:2.4;}else{if(d<60&&R.lineOfSight(s,e,target))partyHurt(target,spec.damage);e.cooldown=1.1;}}continue;}if(d<(spec.boss?330:210)&&R.lineOfSight(s,e,target)){if(d<(spec.boss?130:45)&&e.cooldown<=0){e.windup=spec.boss?.95:.45;continue;}if(d>34&&!(spec.boss&&d<85)){const dx=(target.x-e.x)/(d||1)*spec.speed*dt,dy=(target.y-e.y)/(d||1)*spec.speed*dt;if(R.walkable(s,e.x+dx,e.y))e.x+=dx;if(R.walkable(s,e.x,e.y+dy))e.y+=dy;}}}
for(const bullet of rt.projectiles){const from={x:bullet.x,y:bullet.y};bullet.x+=bullet.vx*dt;bullet.y+=bullet.vy*dt;bullet.life-=dt;if(R.campBlocksProjectile(s,from,bullet))bullet.life=0;if(bullet.life<=0)continue;if(!R.walkable(s,bullet.x,bullet.y,2))bullet.life=0;for(const target of [s,...s.party.filter(p=>p.hp>0)])if(Math.hypot(bullet.x-target.x,bullet.y-target.y)<20){partyHurt(target,bullet.damage||12);bullet.life=0;break;}}rt.projectiles=rt.projectiles.filter(b=>b.life>0);}
function update(dt){if(paused())return;rt.paperHurt=Math.max(0,rt.paperHurt-dt);for(const f of rt.paperFx)f.life-=dt;rt.paperFx=rt.paperFx.filter(f=>f.life>0);const mechanism=R.stepStoryMechanisms?.(s,dt);if(mechanism){if(mechanism.text)notify(mechanism.text);updateHud();if(mechanism.important)save();}rt.travelCooldown=Math.max(0,rt.travelCooldown-dt);s.playtime+=dt;if(R.tickDayNight(s,rt.mobs,dt))notify(R.dayClock(s).night?'夜幕降臨：野外怪物強度 ×2，迷宮 ×1.5。':'天亮了，怪物恢復白天強度。');rt.attack=Math.max(0,rt.attack-dt);rt.attackCd=Math.max(0,rt.attackCd-dt);rt.dash=Math.max(0,rt.dash-dt);rt.dashCd=Math.max(0,rt.dashCd-dt);rt.invuln=Math.max(0,rt.invuln-dt);const wasGuard=rt.guard;rt.guard=keys.has('guard');if(rt.guard){if(!wasGuard){rt.guardAge=0;rt.guardPerfectUsed=false;const practice=R.practiceAction?.(s,'guard');if(practice){notify(practice);updateHud();save();}}rt.guardAge+=dt;}else rt.guardAge=1;if(keys.has('charge'))rt.charge=Math.min(1.1,rt.charge+dt);for(const id of Object.keys(rt.skillCd))rt.skillCd[id]=Math.max(0,rt.skillCd[id]-dt);s.stamina=Math.min(RULES.staminaMax,s.stamina+dt*R.staminaRecovery(s,rt.guard));let dx=(keys.has('right')?1:0)-(keys.has('left')?1:0),dy=(keys.has('down')?1:0)-(keys.has('up')?1:0);if(dx||dy){rt.path=[];rt.target=null;}else if(rt.path.length){const p=rt.path[0],d=Math.hypot(p.x-s.x,p.y-s.y);if(d<5){rt.path.shift();}else{dx=(p.x-s.x)/d;dy=(p.y-s.y)/d;}}if(rt.dash>0&&!dx&&!dy){dx=s.facing.x;dy=s.facing.y;}const n=Math.hypot(dx,dy);rt.moving=n>0;if(n>0){dx/=n;dy/=n;s.facing={x:dx,y:dy};const speed=rt.dash>0?RULES.dashSpeed:keys.has('charge')?RULES.chargeSpeed:rt.guard?RULES.guardSpeed:RULES.walkSpeed;R.move(s,dx*speed*dt,dy*speed*dt);}if(rt.travelCooldown===0){const crossing=R.automaticTravel(s);if(crossing){transition(crossing);return;}}if(rt.target){const target=R.objects(s).find(o=>o.id===rt.target);if(target&& !['exit','location','dungeon'].includes(target.type)&&R.dist(s,target)<76){rt.path=[];rt.target=null;interact();}else if(!rt.path.length)rt.target=null;}if(keys.has('attack'))attack();for(const event of R.stepParty(s,R.isCampSafe(s)?[]:rt.mobs,dt)){if(event.kind==='damage'){if(R.isCampSafe(s,{x:event.x,y:event.y}))continue;rt.magic.push({x:event.x,y:event.y,tx:event.enemy.x,ty:event.enemy.y,element:event.element,life:.3});damageEnemy(event.enemy,event.amount,event.element);}else{paperEffect('flower',event.x,event.y-18);rt.fx.push({x:event.x,y:event.y-50,text:event.text,life:1,color:'#dfeebe'});}}enemyUpdate(dt);R.protectCamps(s,rt.mobs);if(fallen)return;R.updateSpawns(s,rt.mobs);const peace=R.updateEcology?.(s,rt.mobs);if(peace)notify(peace);const discovery=R.updateWorld?.(s);if(discovery)notify(discovery);rt.mobs=rt.mobs.filter(e=>!e.wild||e.hp>0);rt.magic.forEach(b=>b.life-=dt);rt.magic=rt.magic.filter(b=>b.life>0);rt.fx.forEach(f=>f.life-=dt);rt.fx=rt.fx.filter(f=>f.life>0);hudTimer+=dt;autoTimer+=dt;if(hudTimer>.12){updateHud();hudTimer=0;const o=R.nearest(s);$('interact-prompt').hidden=!o;$('interact-prompt').querySelector('span').textContent=o?o.name:'';}if(autoTimer>20){autoTimer=0;if(!rt.mobs.some(e=>e.hp>0&&R.dist(s,e)<200))save();}}
function action(name){soundtrack.unlock();tone(400,.025,'sine',.04);if(name==='death-revive'){revive();return;}if(name==='death-load'){if(fallen)slotsMenu('load');return;}if(name==='death-menu'){if(fallen)deathMenu();return;}if(fallen&&!['close','load-game','load-title','confirm','cancel-confirm','import'].includes(name))return;if(name==='return-forge'){forgeMenu();return;}if(name==='inventory-equipment'){uiTabs.inventory='equipment';inventory();return;}if(name==='inventory-character'){uiTabs.inventory='character';inventory();return;}if(name==='clear-comparison'){comparisonGear=null;if(!fallen&&mode==='game')inventory();return;}if(name==='continue'){const rec=latest();if(rec)start(rec.state);return;}if(name==='new'){newMenu();return;}if(name==='begin'){pendingNew=R.create($('new-name').value,$('new-difficulty').value);introIndex=0;introPage();return;}if(name==='intro-next'){if(++introIndex>=INTRO.length)enterNew();else introPage();return;}if(name==='skip-intro'){enterNew();return;}if(name==='story'){modal('星燈與歸途','<p class="story-page">青苔村外的古堡，有一盞指引旅人歸途的星燈。\n當星燈熄滅，星光散落在森林、月溪與舊塔。\n你將帶著一只行囊，走過迷霧，找回散落的光，也找回守燈者遺忘的約定。</p><div class="modal-actions"><button class="primary" data-action="close">故事，等你繼續</button></div>','story');return;}if(name==='credits'){modal('關於這段旅程','<p>紙境冒險：星燈守望</p><p>一場可離線遊玩的單人 RPG。三章旅程、Lv.30 成長、即時戰鬥、迷宮與支線任務，以及等待點亮的星燈。</p><p>沿用紙雕勇者與道具素材；場景、角色互動、戰鬥與故事為本作設計。音樂為本作原創配樂；動作音效與環境聲由遊戲即時合成。</p><div class="modal-actions"><button data-action="close">返回</button></div>','credits');return;}if(name==='ending-clues'){uiTabs.journal='ending';journal();return;}if(name==='ending-replay'){if(R.endingState(s).finished)ending();return;}if(name==='close'){closeModal();return;}if(name==='pause'){pauseMenu();return;}if(name==='party'){if(mode==='game')partyMenu();return;}if(name==='inventory'){if(mode==='game')inventory();return;}if(name==='journey'){if(mode==='game')journeyMenu();return;}if(name==='export-journey'){if(mode==='game')exportJourney();return;}if(name==='journal'){if(mode==='game')journal();return;}if(name==='map'){if(mode==='game')mapMenu();return;}if(name==='save'){if(mode==='game')slotsMenu('save');return;}if(name==='load-title'||name==='load-game'){slotsMenu('load');return;}if(name==='settings'){settingsMenu();return;}if(name==='export'){exportSave();return;}if(name==='import'){$('save-import').click();return;}if(/^quick-[0-2]$/.test(name)){useQuickItem(Number(name.at(-1)));return;}if(name==='interact'){interact();return;}if(name==='confirm'){const fn=pendingAction;pendingAction=null;fn?.();return;}if(name==='cancel-confirm'){pendingAction=null;if(fallen)slotsMenu('load');else mode==='game'?pauseMenu():closeModal();return;}if(name==='title-confirm'){confirm('在這裡暫別？','會先自動儲存目前旅程，再回到開始畫面。',()=>{save();mode='title';closeModal();$('title-screen').hidden=false;$('hud').hidden=true;clearInput();updateTitle();});return;}if(name==='fullscreen'){try{if(document.fullscreenElement)document.exitFullscreen();else $('game-shell').requestFullscreen()?.catch(()=>notify('這個瀏覽器不支援全螢幕。'));}catch{notify('這個瀏覽器不支援全螢幕。');}return;}}
function wearEquipment(kind,amount=1){const messages=[];if(kind==='weapon'||kind==='body')messages.push(R.wearGear(s,kind,amount));messages.push(R.wearGear(s,'charm',1));const text=messages.filter(Boolean).join('\n');if(text)notify(text);}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-ui-tab]');if(tab){chooseTab(tab.dataset.uiTab);return;}const page=e.target.closest('[data-page-step]');if(page){const info=uiPageInfo[page.dataset.pageKey],step=Number(page.dataset.pageStep);if(info?.owner===overlayPage&&[-1,1].includes(step)){uiPages[page.dataset.pageKey]=Math.max(0,Math.min(info.total-1,(uiPages[page.dataset.pageKey]||0)+step));nextModalFocus=page.id||'';refreshInterface();}return;}const sources=e.target.closest('[data-recipe-sources]');if(sources){recipeSources(sources.dataset.recipeSources);return;}const preview=e.target.closest('[data-gear-preview]');if(preview){comparisonGear=R.compareCharacterStats(s,preview.dataset.gearPreview)?preview.dataset.gearPreview:null;uiTabs.inventory='character';const spec=R.GEAR[preview.dataset.gearPreview];uiTabs.ability=spec?.slot==='weapon'?'attack':spec?.slot==='body'?'defense':(spec?.mana||spec?.stamina||spec?.base==='moon'?'recovery':'defense');inventory();return;}const equipGear=e.target.closest('[data-gear-equip]');if(equipGear){comparisonGear=null;const result=R.equipGear(s,equipGear.dataset.gearEquip);notify(result.text);overlayPage==='forge'?forgeMenu():inventory();updateHud();save();return;}const craft=e.target.closest('[data-craft]');if(craft){const result=R.craftGear(s,craft.dataset.craft);notify(result.text);forgeMenu();if(result.ok){tone(880,.3,'sine',.14);save();}updateHud();return;}const repair=e.target.closest('[data-repair]');if(repair){const result=R.repairGear(s,repair.dataset.repair);notify(result.text);forgeMenu();if(result.ok)save();updateHud();return;}const buyGear=e.target.closest('[data-buy-gear]');if(buyGear){const result=R.buyGear(s,buyGear.dataset.buyGear);notify(result.text);shop();if(result.ok)save();updateHud();return;}const tracked=e.target.closest('[data-track-task]');if(tracked){if(R.trackTask?.(s,tracked.dataset.trackTask)){journal();updateHud();save();}return;}const a=e.target.closest('[data-action]');if(a){action(a.dataset.action);return;}const skill=e.target.closest('[data-skill]');if(skill){cast(skill.dataset.skill);return;}const equip=e.target.closest('[data-equip]');if(equip){R.equipGear(s,equip.dataset.equip);inventory();updateHud();save();return;}const relic=e.target.closest('[data-relic]');if(relic){R.equipGear(s,relic.dataset.relic);inventory();save();return;}const modeButton=e.target.closest('[data-party-mode]');if(modeButton){s.partyMode=modeButton.dataset.partyMode;partyMenu();save();return;}const nextChapter=e.target.closest('[data-next-chapter]');if(nextChapter){if(R.advanceChapter(s,+nextChapter.dataset.nextChapter)){start(s);save();dialogue(R.CHAPTERS[R.chapter(s)-1].title,R.CHAPTERS[R.chapter(s)-1].intro);}return;}const choice=e.target.closest('[data-choice]');if(choice){const result=R.resolveChoice(s,choice.dataset.choiceRoom,choice.dataset.choiceRoom==='guiding-pact-plan'&&choice.dataset.choice==='save-name'?'name:'+($('continuing-name')?.value||''):choice.dataset.choice);closeModal();if(result){if(result.text)notify(result.text);if(result.choice)choiceMenu(result.choice);updateHud();save();}return;}const use=e.target.closest('[data-use]');if(use){useItem(use.dataset.use);return;}const gear=e.target.closest('[data-purchase]');if(gear){if(R.purchase(s,gear.dataset.purchase)){shop();updateHud();save();}return;}const buy=e.target.closest('[data-buy]');if(buy){if(R.buy(s,buy.dataset.buy)){tone(740,.12);shop();updateHud();save();}return;}const destination=e.target.closest('[data-map-target]');if(destination&&s.map==='overworld'){const p=(R.worldPlaces?.(s)||R.WORLD_LOCATIONS).find(p=>p.id===destination.dataset.mapTarget);if(p){closeModal();rt.path=R.pathfind(s,p.x,p.y);rt.target=p.id;notify('前往'+p.name+'。走進圖示後會自動進入。');}return;}const upgrade=e.target.closest('[data-upgrade]');if(upgrade){if(R.upgrade(s,upgrade.dataset.upgrade)){tone(820,.2);shop();updateHud();save();}return;}const slot=e.target.closest('[data-slot-action]');if(slot){const index=slot.dataset.slot==='auto'?'auto':+slot.dataset.slot;if(slot.dataset.slotAction==='save'){const fn=()=>{const ok=save(index);slotsMenu('save');notify(ok?'已儲存到欄位 '+(index+1):'瀏覽器無法寫入，請匯出存檔。');};if(db.slots[index])confirm('覆寫這個存檔？','會以目前的角色與旅程取代存檔 '+(index+1)+'。',fn);else fn();}else{const rec=index==='auto'?db.auto:db.slots[index];if(rec){const fn=()=>{start(rec.state);save();notify('旅程已讀取。');};if(mode==='game')confirm('回到這段旅程？','目前未儲存的變化將被取代。',fn);else fn();}}}});
function channelVolume(e){const channels={'music-volume-setting':'musicVolume','sfx-volume-setting':'sfxVolume','ambient-volume-setting':'ambientVolume','volume-setting':'volume'};const field=channels[e.target.id];if(!field)return;const value=Number(e.target.value);if(!Number.isFinite(value))return;settings[field]=Math.max(0,Math.min(1,value/100));saveSettings();}
document.addEventListener('input',channelVolume);
document.addEventListener('change',e=>{if(/^quick-slot-[0-2]$/.test(e.target.id)){const index=Number(e.target.id.at(-1));if(QUICK_ITEMS.includes(e.target.value)){settings.quickItems[index]=e.target.value;saveSettings();updateHud();}return;}channelVolume(e);if(e.target.id==='effects-setting'){settings.effects=e.target.value==='on';saveSettings();}if(e.target.id==='sound-setting'){settings.sound=e.target.value==='on';saveSettings();}if(e.target.id==='volume-setting'||e.target.id==='sfx-volume-setting')tone(520,.15);});
const directions={w:'up',W:'up',ArrowUp:'up',s:'down',S:'down',ArrowDown:'down',a:'left',A:'left',ArrowLeft:'left',d:'right',D:'right',ArrowRight:'right'};
// Prefer physical key positions so the layout also works with a Chinese input method.
function inputKey(e){if(/^Key[A-Z]$/.test(e.code||''))return e.code.slice(3).toLowerCase();if(/^Digit[0-9]$/.test(e.code||''))return e.code.slice(5);if(e.code==='Space')return ' ';return typeof e.key==='string'&&e.key.length===1?e.key.toLowerCase():e.key;}
window.addEventListener('keydown',e=>{
 if(e.ctrlKey||e.altKey||e.metaKey)return;
 const key=inputKey(e);
 if(!e.target.closest('input,select,textarea')&&key==='Tab'&&!$('overlay').hidden){const list=[...$('overlay').querySelectorAll('button:not([disabled]),input,select')].filter(el=>!el.hidden&&el.tabIndex!==-1);const first=list[0],end=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();end?.focus();}else if(!e.shiftKey&&document.activeElement===end){e.preventDefault();first?.focus();}return;}
 if(e.target.closest('input,select,textarea'))return;const focusedTab=e.target.closest('[data-ui-tab]');if(focusedTab&&!$('overlay').hidden&&['ArrowLeft','ArrowRight','Home','End'].includes(key)){const [kind,id]=focusedTab.dataset.uiTab.split(':'),list=UI_TABS[kind];if(list&&UI_OWNERS[kind]===overlayPage){e.preventDefault();if(!e.repeat){const at=list.findIndex(t=>t[0]===id),next=key==='Home'?0:key==='End'?list.length-1:(at+(key==='ArrowRight'?1:-1)+list.length)%list.length;chooseTab(kind+':'+list[next][0]);}}return;}
 if(!$('dialogue').hidden){if(['Enter',' ','e'].includes(key)){e.preventDefault();if(!e.repeat)advanceDialogue();}return;}
 if(key==='Escape'){e.preventDefault();if(e.repeat||overlayPage==='intro'||overlayPage==='ending'||overlayPage==='death')return;if(!$('overlay').hidden)closeModal();else if(mode==='game')pauseMenu();return;}
 const menus={z:['inventory',inventory],x:['journal',journal],c:['map',mapMenu],v:['party',partyMenu]};
 if(menus[key]&&mode==='game'&&!fallen&&!rt.transition&&($('overlay').hidden||['inventory','journal','map','party','pause'].includes(overlayPage))){e.preventDefault();if(!e.repeat){const [page,open]=menus[key];overlayPage===page?closeModal():open();}return;}
 if(paused())return;
 if(directions[key]){e.preventDefault();keys.add(directions[key]);return;}
 if(key==='j'){e.preventDefault();keys.add('attack');if(!e.repeat)attack();return;}
 if(![' ','e','Enter','Shift','k','u','i','o','h','l','1','2','3'].includes(key))return;
 e.preventDefault();if(e.repeat)return;
 if(key===' '||key==='e'||key==='Enter')interact();
 if(key==='Shift'||key==='k')dash();
 if(['u','i','o'].includes(key))cast({u:'fire',i:'heal',o:'thunder'}[key]);
 if(key==='h')beginCharge();
 if(key==='l')keys.add('guard');
 if(['1','2','3'].includes(key))useQuickItem(Number(key)-1);
});
window.addEventListener('keyup',e=>{const key=inputKey(e);if(key==='h')releaseCharge();if(directions[key])keys.delete(directions[key]);if(key==='l')keys.delete('guard');if(key==='j')keys.delete('attack');});window.addEventListener('blur',()=>{soundtrack.setVisible(false);clearInput();if(mode==='game'&&!paused())pauseMenu();});window.addEventListener('focus',()=>soundtrack.setVisible(!document.hidden));window.addEventListener('pagehide',()=>soundtrack.setVisible(false));window.addEventListener('pageshow',()=>soundtrack.setVisible(!document.hidden));document.addEventListener('visibilitychange',()=>{soundtrack.setVisible(!document.hidden&&(document.hasFocus?document.hasFocus():true));if(document.hidden&&mode==='game'){clearInput();save();if(!paused())pauseMenu();}});
for(const b of document.querySelectorAll('[data-dir],[data-touch]')){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(b.dataset.dir)keys.add(b.dataset.dir);if(b.dataset.touch==='attack'){keys.add('attack');attack();}if(b.dataset.touch==='dash')dash();if(b.dataset.touch==='guard')keys.add('guard');if(b.dataset.touch==='charge')beginCharge();});const up=e=>{if(b.dataset.touch==='charge')releaseCharge(e?.type!=='pointerup');if(b.dataset.dir)keys.delete(b.dataset.dir);if(b.dataset.touch==='attack')keys.delete('attack');if(b.dataset.touch==='guard')keys.delete('guard');};b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up);}
canvas.addEventListener('pointerdown',e=>{if(paused())return;canvas.focus({preventScroll:true});const p=renderer.toWorld(e.clientX,e.clientY),o=R.objects(s).filter(o=>Math.hypot(o.x-p.x,o.y-20-p.y)<43).sort((a,b)=>R.dist(p,a)-R.dist(p,b))[0];if(o&&!['location','exit','dungeon'].includes(o.type)&&R.dist(s,o)<85){rt.target=null;rt.path=[];interactNearest(o);return;}const target=o||p;rt.path=R.pathfind(s,Math.floor(target.x/48),Math.floor(target.y/48));rt.target=o?.id||null;});
function interactNearest(o){const result=R.nearest(s);if(!['location','exit','dungeon'].includes(o.type)&&result?.id===o.id)interact();else{rt.path=R.pathfind(s,Math.floor(o.x/48),Math.floor(o.y/48));rt.target=o.id;}}
window.addEventListener('resize',()=>{renderer.resize();if(!$('overlay').hidden)refreshInterface();});
function frame(now){const dt=Math.min(.04,Math.max(0,(now-last)/1000));last=now;clock+=dt;R.recordJourney?.(s,rt,dt,{mode,hidden:document.hidden,reading:!$('dialogue').hidden,menu:!$('overlay').hidden?(['forge','craft-sources'].includes(overlayPage)?'inventory':overlayPage):null,paused:paused()});const stopped=settings.effects&&rt.hitstop>0;rt.hitstop=Math.max(0,rt.hitstop-dt);rt.shake=Math.max(0,rt.shake-dt*9);if(!settings.effects)rt.shake=0;update(stopped?0:dt);if(toastTimer>0&&((toastTimer-=dt)<=0))$('toast').classList.remove('show');if(announceTimer>0&&((announceTimer-=dt)<=0))$('region-announcement').classList.remove('show');if(saveTimer>0&&((saveTimer-=dt)<=0))$('autosave-label').classList.remove('show');soundtrack.update(window.PaperAudio.sceneFor(R,s,{mode,page:$('overlay').hidden?null:overlayPage,reading:!$('dialogue').hidden,mobs:rt.mobs}),dt);rt.paperEffects=settings.effects;rt.paperPaused=paused();if(!settings.effects){rt.paperFx=[];rt.paperHurt=0;}renderer.render(rt.travelView||s,rt,clock,mode==='title');requestAnimationFrame(frame);}
updateTitle();renderer.resize();requestAnimationFrame(frame);
})();
